      const x = side * (13 + rand() * 5);
      const h = 5 + rand() * 4;
      const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.3, h, 6), trunkMat);
      trunk.position.set(x, h / 2, z); trunk.rotation.z = side * 0.06; scene.add(trunk);
      for (let i = 0; i < 7; i++) {
        const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.7, 3.4, 4), leafMat);
        const a = (i / 7) * Math.PI * 2;
        leaf.position.set(x + Math.cos(a) * 1.1, h + 0.2 + Math.sin(a) * 0.2, z + Math.sin(a) * 1.1);
        leaf.rotation.z = Math.cos(a) * 1.2; leaf.rotation.x = Math.sin(a) * 1.2;
        leaf.scale.set(0.5, 1, 0.5);
        scene.add(leaf);
      }
    }
  }
}

function addFields(scene, distance) {
  const rand = rng(901);
  const water = new THREE.MeshPhongMaterial({ color: 0x355f5a, emissive: 0x152c2b, emissiveIntensity: 0.2, shininess: 70 });
  const soil = toon(0x5e543d);
  for (const side of [-1, 1]) {
    for (let i = 0; i < 18; i++) {
      const x = side * (18 + (i % 4) * 17);
      const z = 18 - (i * 28 + rand() * 15);
      if (z < -distance - 80) continue;
      const p = new THREE.Mesh(new THREE.PlaneGeometry(12, 18), water);
      p.rotation.x = -Math.PI / 2; p.position.set(x, -0.08, z); scene.add(p);
      for (let r = 0; r < 3; r++) {
        const furrow = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.06, 18), soil);
        furrow.position.set(x - 4 + r * 4, 0.02, z); scene.add(furrow);
      }
      if (rand() > 0.6) {
        const house = rounded(4.4, 2.8, 3.8, 0.25, toon(0xe8dfcb));
        house.position.set(x + side * 8, 1.4, z + 5); scene.add(house);
        const roof = new THREE.Mesh(new THREE.ConeGeometry(3.7, 1.8, 4), toon(0x39334b));
        roof.rotation.y = Math.PI / 4; roof.position.set(x + side * 8, 3.7, z + 5); scene.add(roof);
        const warm = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.45), basic(0xffcf73));
        warm.position.set(x + side * 8 - side * 2.21, 1.5, z + 5); warm.rotation.y = side * Math.PI / 2; scene.add(warm);
      }
    }
  }
}

function addTorii(scene, x, z, scale = 1, color = 0xe13a43) {
  const g = new THREE.Group();
  const red = toon(color);
  const black = toon(0x1a1518);
  for (const sx of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.38, 6, 8), red);
    post.position.set(sx * 3.2, 3, 0); g.add(post);
  }
  const top = new THREE.Mesh(new THREE.BoxGeometry(8.4, 0.65, 0.55), red);
  top.position.y = 6.1; g.add(top);
  const beam = new THREE.Mesh(new THREE.BoxGeometry(6.8, 0.4, 0.4), red);
  beam.position.y = 5.2; g.add(beam);
  const crown = new THREE.Mesh(new THREE.BoxGeometry(9.2, 0.25, 0.7), black);
  crown.position.y = 6.5; g.add(crown);
  g.position.set(x, 0, z); g.scale.setScalar(scale);
  g.rotation.y = Math.PI / 2;
  scene.add(g);
  return g;
}

function addHologram(scene, distance, cfg) {
  const g = new THREE.Group();
  const colors = [cfg.glow, cfg.accent, 0xa34dff];
  for (let i = 0; i < 8; i++) {
    const z = -40 - i * (distance / 8);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(11 + i * 0.4, 0.09, 6, 48), basic(colors[i % 3], 0.65));
    ring.position.set(0, 7 + Math.sin(i) * 1.4, z);
    ring.rotation.x = Math.PI / 2;
    g.add(ring);
    const ring2 = new THREE.Mesh(new THREE.TorusGeometry(8 + i * 0.3, 0.05, 6, 40), basic(colors[(i + 1) % 3], 0.45));
    ring2.position.copy(ring.position); ring2.rotation.x = Math.PI / 2; ring2.rotation.z = i * 0.25;
    g.add(ring2);
    const pillarMat = basic(colors[i % 3], 0.35);
    for (const side of [-1, 1]) {
      const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.09, 15, 0.09), pillarMat);
      pillar.position.set(side * 16, 7.5, z); g.add(pillar);
    }
  }
  // Neon grid ground off the shoulders.
  const grid = new THREE.GridHelper(400, 40, cfg.accent, cfg.glow);
  grid.position.set(0, -0.05, -distance / 2);
  grid.material.transparent = true; grid.material.opacity = 0.23;
  scene.add(grid);
  scene.add(g);
  return g;
}

function addGarage(scene, cfg, distance) {
  const wallMat = toon(0x1d1a23);
  const ribMat = toon(0x302b39);
  const ceilingY = 9.2;
  for (const side of [-1, 1]) {
    const wall = new THREE.Mesh(new THREE.BoxGeometry(0.5, ceilingY, distance + 130), wallMat);
    wall.position.set(side * 16, ceilingY / 2, -distance / 2 + 10); scene.add(wall);
    for (let z = 30; z > -distance - 80; z -= 28) {
      const col = new THREE.Mesh(new THREE.BoxGeometry(1.1, ceilingY, 1.1), ribMat);
      col.position.set(side * 12.5, ceilingY / 2, z); scene.add(col);
      const neon = new THREE.Mesh(new THREE.BoxGeometry(0.1, 5.0, 0.12), basic(side > 0 ? cfg.accent : cfg.glow));
      neon.position.set(side * 11.92, 3.1, z); scene.add(neon);
      const light = new THREE.PointLight(side > 0 ? cfg.accent : cfg.glow, 0.8, 22, 2);
      light.position.set(side * 9, 4.5, z); scene.add(light);
    }
  }
  const ceiling = new THREE.Mesh(new THREE.BoxGeometry(32, 0.4, distance + 130), toon(0x131118));
  ceiling.position.set(0, ceilingY, -distance / 2 + 10); scene.add(ceiling);
  for (let z = 20; z > -distance - 60; z -= 14) {
    const tube = new THREE.Mesh(new THREE.BoxGeometry(12, 0.08, 0.12), basic(cfg.warm));
    tube.position.set(0, ceilingY - 0.35, z); scene.add(tube);
  }
  // Ceiling signage.
  for (let i = 0; i < 6; i++) {
    const z = -35 - i * 100;
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(8, 1.5), new THREE.MeshBasicMaterial({ map: signTexture('地下駐車場', i % 2 ? cfg.accent : cfg.glow, { vertical: false, fontSize: 88, sub: 'LEVEL ' + (i + 1) }), side: THREE.DoubleSide, toneMapped: false }));
    sign.position.set(0, 7.6, z); scene.add(sign);
  }
}

function addAirport(scene, cfg, distance) {
  const rand = rng(618);
  // hangars and runway lights
  for (const side of [-1, 1]) {
    for (let i = 0; i < 4; i++) {
      const z = -50 - i * 170;
      const hangar = rounded(18, 8, 24, 0.3, toon(0x3a4355));
      hangar.position.set(side * 36, 4, z); scene.add(hangar);
      const door = new THREE.Mesh(new THREE.PlaneGeometry(13, 6), toon(0x1c2230));
      door.position.set(side * (36 - 9.02), 3.3, z); door.rotation.y = side * -Math.PI / 2; scene.add(door);
    }
    for (let z = 30; z > -distance - 120; z -= 20) {
      const light = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.16, 0.35), basic(cfg.accent));
      light.position.set(side * 14, 0.2, z); scene.add(light);
    }
  }
  // Control tower.
  const tower = new THREE.Group();
  const body = rounded(4, 16, 4, 0.2, toon(0xcad4df));
  body.position.y = 8; tower.add(body);
  const cabin = rounded(7, 3.5, 7, 0.2, toon(0x202c3f));
  cabin.position.y = 17; tower.add(cabin);
  const glassBand = new THREE.Mesh(new THREE.BoxGeometry(7.1, 1.3, 7.1), basic(0x7ad8ff, 0.5));
  glassBand.position.y = 17.5; tower.add(glassBand);
  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.4, 8, 6), basic(0xff3b4e));
  beacon.position.y = 20; tower.add(beacon);
  tower.position.set(34, 0, -90); scene.add(tower);
  // Planes.
  for (let i = 0; i < 3; i++) {
    const plane = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(1.1, 9, 4, 8), toon(0xf0f2ef));
    body.rotation.z = Math.PI / 2; plane.add(body);
    const wing = new THREE.Mesh(new THREE.BoxGeometry(16, 0.25, 2.6), toon(0xe4e9ee));
    wing.position.y = 0.1; plane.add(wing);
    const tail = new THREE.Mesh(new THREE.BoxGeometry(3.2, 1.9, 0.25), toon(0xff4d58));
    tail.position.set(-4.6, 0.9, 0); plane.add(tail);
    plane.position.set(-45 - i * 18, 0.6, -140 - i * 150);
    plane.rotation.y = 0.3 + rand() * 0.4;
    scene.add(plane);
  }
}

function addCountryside(scene, cfg, distance) {
  addMountains(scene, cfg, distance, 0.8);
  addFields(scene, distance);
  const rand = rng(771);
  // Power lines.
  for (const side of [-1, 1]) {
    for (let z = 24; z > -distance - 100; z -= 45) {
      const x = side * 12.4;
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.16, 8.5, 5), toon(0x4c4038));
      pole.position.set(x, 4.25, z); scene.add(pole);
      const arm = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.13, 0.13), toon(0x4c4038));
      arm.position.set(x, 7.5, z); scene.add(arm);
    }
    const lineMat = new THREE.LineBasicMaterial({ color: 0x1e1c22, transparent: true, opacity: 0.8 });
    for (let j = 0; j < 2; j++) {
      const pts = [];
      for (let z = 24; z > -distance - 100; z -= 45) pts.push(new THREE.Vector3(side * 12.4 + (j ? 1.4 : -1.4), 7.5, z));
      new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat).let?.();
      const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat);
      scene.add(line);
    }
  }
  // Torii over the strip.
  for (let i = 0; i < 3; i++) addTorii(scene, 0, -120 - i * 220, 1.4, i === 1 ? 0xe47648 : 0xe13a43);
}

function addRain(scene, range = 70, count = 700) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 6);
  const rand = rng(44);
  for (let i = 0; i < count; i++) {
    const x = (rand() - 0.5) * 80;
    const y = rand() * 40;
    const z = 25 - rand() * range;
    positions[i * 6] = x; positions[i * 6 + 1] = y; positions[i * 6 + 2] = z;
    positions[i * 6 + 3] = x + 0.04; positions[i * 6 + 4] = y - 1.2; positions[i * 6 + 5] = z;
  }
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.LineBasicMaterial({ color: 0x9fdfff, transparent: true, opacity: 0.24, blending: THREE.AdditiveBlending, depthWrite: false });
  const rain = new THREE.LineSegments(geo, mat);
  scene.add(rain);
  return { mesh: rain, positions, count };
}

export function createShowroom(scene) {
  scene.background = new THREE.Color(0x08060f);
  scene.fog = new THREE.Fog(0x08060f, 18, 55);
  const group = new THREE.Group();
  const floorMat = new THREE.MeshStandardMaterial({ color: 0x14111d, roughness: 0.28, metalness: 0.68 });
  const floor = new THREE.Mesh(new THREE.CircleGeometry(20, 48), floorMat);
  floor.rotation.x = -Math.PI / 2; group.add(floor);
  const disc = new THREE.Mesh(new THREE.CylinderGeometry(3.35, 3.5, 0.18, 48), new THREE.MeshStandardMaterial({ color: 0x1b1725, roughness: 0.2, metalness: 0.9 }));
  disc.position.y = 0.09; group.add(disc);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(3.4, 0.06, 8, 64), new THREE.MeshBasicMaterial({ color: 0xff2d9a, toneMapped: false }));
  rim.rotation.x = Math.PI / 2; rim.position.y = 0.19; group.add(rim);
  const rim2 = new THREE.Mesh(new THREE.TorusGeometry(4.7, 0.025, 8, 64), new THREE.MeshBasicMaterial({ color: 0x29f3e0, toneMapped: false }));
  rim2.rotation.x = Math.PI / 2; rim2.position.y = 0.02; group.add(rim2);
  const grid = new THREE.GridHelper(36, 36, 0x2c2740, 0x1b1828);
  grid.position.y = 0.005; group.add(grid);

  const bg = new THREE.Mesh(new THREE.PlaneGeometry(50, 22), new THREE.MeshBasicMaterial({ color: 0x0b0714 }));
  bg.position.set(0, 10, -19); group.add(bg);

  // Stylised city silhouette.
  const rand = rng(5);
  for (let i = 0; i < 26; i++) {
    const side = i % 2 ? 1 : -1;
    const w = 2 + rand() * 4;
    const h = 3 + rand() * 11;
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, 2 + rand() * 3), new THREE.MeshToonMaterial({ color: 0x191426 }));
    b.position.set(side * (6 + rand() * 17), h / 2, -12 - rand() * 20);
    group.add(b);
    for (let k = 0; k < 4; k++) {
      if (rand() > 0.45) {
        const win = new THREE.Mesh(new THREE.PlaneGeometry(0.35, 0.22), new THREE.MeshBasicMaterial({ color: NEON_COLORS[Math.floor(rand() * NEON_COLORS.length)], transparent: true, opacity: 0.6 }));
        win.position.set(b.position.x + (rand() - 0.5) * w * 0.6, 1 + rand() * h * 0.8, -12 + w / 2 + 0.02);
        group.add(win);
      }
    }
  }

  // Neon arch frames behind the car.
  for (const [x, color] of [[-7, 0x22e4ff], [7, 0xff2d9a]]) {
    const arch = new THREE.Group();
    const bar = new THREE.Mesh(new THREE.TorusGeometry(4.2, 0.035, 6, 32, Math.PI), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
    bar.rotation.z = 0; bar.position.y = 4; arch.add(bar);
    const line = new THREE.Mesh(new THREE.BoxGeometry(0.05, 4, 0.05), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
    line.position.set(-4.2, 2, 0); arch.add(line);
    const line2 = line.clone(); line2.position.x = 4.2; arch.add(line2);
    arch.position.set(x, 0, -4.2);
    group.add(arch);
  }

  // Hanging lanterns.
  for (let i = 0; i < 12; i++) {
    const color = NEON_COLORS[i % NEON_COLORS.length];
    const lantern = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 6), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
    lantern.position.set(-6 + (i % 6) * 2.4, 2.8 + Math.floor(i / 6) * 1.1, -3.5);
    group.add(lantern);
    const string = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 1, 4), new THREE.MeshBasicMaterial({ color: 0x292633 }));
    string.position.copy(lantern.position); string.position.y += 0.58; group.add(string);
  }

  // Wall sign.
  const c = canvas2d(1024, 256);
  const x = c.getContext('2d');
  x.fillStyle = '#08060f'; x.fillRect(0, 0, 1024, 256);
  x.strokeStyle = '#ff2d9a'; x.lineWidth = 5; x.strokeRect(6, 6, 1012, 244);
  x.fillStyle = '#ff2d9a'; x.font = '900 150px Bebas Neue, sans-serif'; x.textAlign = 'center';
  x.fillText('TOKYO REDLINE', 512, 145);
  x.fillStyle = '#8ef8eb'; x.font = '900 34px "Noto Sans JP", sans-serif';
  x.fillText('東京 ・ 夜間走行', 512, 210);
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(12.8, 3.2), new THREE.MeshBasicMaterial({ map: texFrom(c), toneMapped: false }));
  sign.position.set(0, 8.8, -18.5);
  group.add(sign);

  // Vertical signs.
  ['夜間', '速度', '夢'].forEach((t, i) => {
    const color = NEON_COLORS[i];
    const ms = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 5.2), new THREE.MeshBasicMaterial({ map: signTexture(t, color), side: THREE.DoubleSide, toneMapped: false }));
    ms.position.set(-13 + i * 13, 5.2, -15.5);
    group.add(ms);
  });

  // Podium lights.
  const key = new THREE.SpotLight(0xffe5d5, 4.5, 40, 0.7, 0.7, 1.2);
  key.position.set(5, 13, 10); key.target.position.set(0, 0.5, 0); group.add(key, key.target);
  const pink = new THREE.PointLight(0xff2d9a, 18, 30, 2); pink.position.set(-8, 4, 2); group.add(pink);
  const cyan = new THREE.PointLight(0x22e4ff, 15, 28, 2); cyan.position.set(8, 3, -2); group.add(cyan);
  const warm = new THREE.PointLight(0xffc56a, 8, 16, 2); warm.position.set(0, 6, 4); group.add(warm);
  const spot = new THREE.PointLight(0xffffff, 5, 12, 2); spot.position.set(0, 5, -3); group.add(spot);

  // Dust/particles.
  const pGeo = new THREE.BufferGeometry();
  const pArr = new Float32Array(220 * 3);
  for (let i = 0; i < 220; i++) {
    pArr[i * 3] = (rand() - 0.5) * 24;
    pArr[i * 3 + 1] = rand() * 9;
    pArr[i * 3 + 2] = (rand() - 0.5) * 18;
  }
  pGeo.setAttribute('position', new THREE.BufferAttribute(pArr, 3));
  const particles = new THREE.Points(pGeo, new THREE.PointsMaterial({ color: 0xb89cff, size: 0.035, transparent: true, opacity: 0.55, depthWrite: false }));
  group.add(particles);

  const hemi = new THREE.HemisphereLight(0x8fcfff, 0x160b22, 1.4);
  group.add(hemi);
  const rimLight = new THREE.DirectionalLight(0x7b9dff, 0.8); rimLight.position.set(-6, 8, -4); group.add(rimLight);

  scene.add(group);
  return {
    group, particles,
    update(t) {
      particles.rotation.y = t * 0.01;
      rim.rotation.z = t * 0.06;
      rim2.rotation.z = -t * 0.04;
      sign.material.opacity = 0.9 + Math.sin(t * 2.2) * 0.1;
    },
    setTheme(track) {
      pink.color.setHex(track.colors.glow);
      cyan.color.setHex(track.colors.accent);
    }
  };
}

export function createRaceEnvironment(scene, track, distance) {
  scene.background = new THREE.Color(track.colors.top);
  scene.fog = new THREE.FogExp2(track.colors.fog, track.kind === 'garage' ? 0.012 : track.kind === 'city' ? 0.0085 : 0.0042);
  const group = new THREE.Group();
  const cfg = track.colors;
  const random = rng((track.id.charCodeAt(0) + distance) | 0);

  addSky(scene, cfg, track.kind);
  if (['city', 'osaka', 'future', 'mountain', 'waterfront', 'harbour', 'garage'].includes(track.kind)) addStars(scene, cfg.accent);

  addRoad(scene, track, distance);
  const gantry = addStartGantry(scene, track, distance);

  const kinds = new Set(track.props || []);
  if (track.kind === 'city' || track.kind === 'future') addCity(scene, track, distance, { seed: 17, tall: track.kind === 'future' });
  if (track.kind === 'osaka') addCity(scene, track, distance, { seed: 30, low: true });
  if (track.kind === 'waterfront') {
    addCity(scene, track, distance, { seed: 48, low: true });
    addWater(scene, cfg, distance, 1);
    addContainers(scene, distance, cfg);
    const ferris = addFerrisWheel(scene, 76, -105, cfg.glow);
    group.userData.ferris = ferris;
  }
  if (track.kind === 'mountain') {
    addMountains(scene, cfg, distance, 1.2);
    addTrees(scene, distance, 0x184c3f, 0xff9ec6);
    addTorii(scene, 0, -70, 1.2, 0xdd3a4b);
  }
  if (track.kind === 'garage') addGarage(scene, cfg, distance);
  if (track.kind === 'harbour') {
    addContainers(scene, distance, cfg);
    addWater(scene, cfg, distance, -1);
    addMountains(scene, cfg, distance, 0.25);
  }
  if (track.kind === 'airport') addAirport(scene, cfg, distance);
  if (track.kind === 'coast') {
    addWater(scene, cfg, distance, 1);
    addPalms(scene, distance);
    addFerrisWheel(scene, 82, -220, cfg.warm);
    addCity(scene, track, distance, { seed: 73, low: true });
  }
  if (track.kind === 'countryside') addCountryside(scene, cfg, distance);
  if (track.kind === 'future') {
    addHologram(scene, distance, cfg);
    addCity(scene, track, distance, { seed: 211, tall: true });
  }

  // Ground mist/haze.
  const haze = new THREE.Mesh(new THREE.PlaneGeometry(350, distance + 500), new THREE.MeshBasicMaterial({ color: cfg.fog, transparent: true, opacity: 0.12, depthWrite: false }));
  haze.rotation.x = -Math.PI / 2; haze.position.set(0, 0.12, -distance / 2); scene.add(haze);

  // Start-line crowd.
  const crowdGroup = new THREE.Group();
  const crowdRand = rng(101);
  const crowdCount = Math.floor(120 * (track.crowd || 1));
  const bodyGeo = new THREE.CapsuleGeometry(0.16, 0.4, 3, 5);
  const headGeo = new THREE.SphereGeometry(0.14, 6, 5);
  const colors = [0xff4d84, 0x3bffd7, 0xffd84a, 0x8d5bff, 0xff7a42, 0xf4efe1];
  const crowdMats = colors.map(c => new THREE.MeshToonMaterial({ color: c }));
  for (let i = 0; i < crowdCount; i++) {
    const side = i % 2 ? 1 : -1;
    const x = side * (15 + crowdRand() * 7);
    const row = Math.floor(crowdRand() * 5);
    const z = 15 - crowdRand() * 55;
    const person = new THREE.Mesh(bodyGeo, crowdMats[Math.floor(crowdRand() * colors.length)]);
    person.position.set(x, 0.85 + row * 0.32, z);
    person.rotation.y = crowdRand() * 6;
    crowdGroup.add(person);
    const head = new THREE.Mesh(headGeo, new THREE.MeshToonMaterial({ color: crowdRand() > 0.5 ? 0xd8a476 : 0x7d573f }));
    head.position.set(x, 1.3 + row * 0.32, z); crowdGroup.add(head);
  }
  scene.add(crowdGroup);

  // Light arch reflections on the ground.
  for (let i = 0; i < 5; i++) {
    const z = -8 - i * (distance / 5);
    const strip = new THREE.Mesh(new THREE.PlaneGeometry(18, 0.7), new THREE.MeshBasicMaterial({ color: i % 2 ? cfg.glow : cfg.accent, transparent: true, opacity: 0.2, blending: THREE.AdditiveBlending, depthWrite: false }));
    strip.rotation.x = -Math.PI / 2; strip.position.set(0, 0.05, z); scene.add(strip);
  }

  let rain = null;
  if (track.rain) rain = addRain(scene);

  // Global light rig.
  const hemi = new THREE.HemisphereLight(cfg.top, 0x1b1119, 1.5); scene.add(hemi);
  const moon = new THREE.DirectionalLight(cfg.accent, 1.25); moon.position.set(-30, 40, -30); scene.add(moon);
  const rim = new THREE.DirectionalLight(cfg.glow, 1.1); rim.position.set(35, 25, 20); scene.add(rim);
  const startLight = new THREE.PointLight(cfg.glow, 12, 60, 2); startLight.position.set(0, 8, -3); scene.add(startLight);
  const finishLight = new THREE.PointLight(cfg.accent, 14, 70, 2); finishLight.position.set(0, 8, -distance); scene.add(finishLight);
  const ambient = new THREE.AmbientLight(0xffffff, 0.22); scene.add(ambient);

  const tempColor = new THREE.Color();
  function setStartLights(step) {
    // step: -1 all off, 0 amber1, 1 amber2, 2 amber3, 3 green.
    for (const set of [gantry.treeLights, gantry.laneLights]) {
      set.forEach((l, i) => {
        let on = false;
        if (step === 3) on = i === 3;
        else if (step >= 0) on = i <= step;
        if (on) {
          l.mat.color.setHex(l.color);
          l.mesh.scale.setScalar(1.2 + (step === 3 ? Math.sin(performance.now() * 0.02) * 0.08 : 0));
        } else {
          l.mat.color.setHex(0x201e26);
          l.mesh.scale.setScalar(1);
        }
      });
    }
    tempColor.setHex(step === 3 ? cfg.accent : step >= 0 ? cfg.warm : cfg.fog);
    startLight.color.copy(tempColor);
    startLight.intensity = step >= 0 ? 16 : 4;
  }
  setStartLights(-1);

  const clockStart = performance.now();
  return {
    group, setStartLights, gantry,
    update(dt, elapsed, speed = 0) {
      if (rain) {
        const p = rain.positions;
        for (let i = 0; i < rain.count; i++) {
          p[i * 6 + 1] -= dt * (32 + speed * 0.8);
          p[i * 6 + 4] -= dt * (32 + speed * 0.8);
          if (p[i * 6 + 1] < 0) {
            p[i * 6 + 1] += 40; p[i * 6 + 4] += 40;
            p[i * 6] = (Math.random() - 0.5) * 80; p[i * 6 + 3] = p[i * 6] + 0.04;
          }
        }
        rain.mesh.geometry.attributes.position.needsUpdate = true;
        rain.mesh.position.z = Math.max(-35, -speed * 0.4);
      }
      if (group.userData.ferris) group.userData.ferris.userData.wheel.rotation.z = elapsed * 0.06;
      // crowd bounce
      // (cheap: only a subtle group bob)
      crowdGroup.position.y = Math.sin(elapsed * 3.1) * 0.03;
    }
  };
}

export { addStars, signTexture, radialTexture, texFrom, makeWindowTexture };

import * as THREE from 'three';
import { createCarModel, GEAR_GATES } from './carModel.js';
import { createRaceEnvironment, radialTexture } from './environment.js';
import { CARS_BY_ID, RIVALS_BY_ID, effectiveStats, DISTANCES, PAINTS } from './data.js';

const FIXED = 1 / 90;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;

function estimateTime(power, weight, meters) {
  const ratio = Math.max(1.8, weight / Math.max(45, power));
  const quarter = 6.85 * Math.pow(ratio, 0.32);
  return meters > 500 ? quarter + 3.7 + 0.017 * quarter * quarter : quarter;
}

function fmtTime(t) {
  if (!Number.isFinite(t) || t < 0) return '--:--.---';
  const m = Math.floor(t / 60);
  const s = Math.floor(t % 60);
  const ms = Math.floor((t % 1) * 1000);
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;
}

export class RaceSession {
  constructor({ track, distance, car, build, rival, audio, onHud, onFinish, onMessage, settings, event = null, isTest = false }) {
    this.track = track;
    this.distance = DISTANCES[distance] || DISTANCES.quarter;
    this.car = car;
    this.build = build;
    this.rivalDef = RIVALS_BY_ID[rival] || RIVALS[0];
    this.audio = audio;
    this.onHud = onHud || (() => {});
    this.onFinish = onFinish || (() => {});
    this.onMessage = onMessage || (() => {});
    this.settings = settings || {};
    this.event = event;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.035, 1200);
    this.camera.rotation.order = 'YXZ';
    this.camera.position.set(4.56, 1.28, 0.1);

    this.stats = effectiveStats(car, build);
    this.playerPower = this.stats.power;
    this.env = createRaceEnvironment(this.scene, track, this.distance.meters);
    this.env.setStartLights(-1);

    this.playerGroup = new THREE.Group();
    this.playerGroup.position.set(4.15, 0, 0);
    this.playerModel = createCarModel(car, build, { cockpitMode: 'race' });
    this.playerGroup.add(this.playerModel.group);
    this.scene.add(this.playerGroup);

    const rivalCar = CARS_BY_ID[this.rivalDef.car] || CARS_BY_ID['nissan-s13'];
    const rivalBuild = {
      paint: 'cyber', bodykit: 'wide', spoiler: 'gt', wheels: 'dish', underglow: 'pink',
      headlights: 'pink', decal: 'kanji', engine: 'stock', turbo: 'street', ecu: 'race',
      exhaust: 'titanium', interior: 'red', seat: 'stock', knob: 'ball'
    };
    this.rivalGroup = new THREE.Group();
    this.rivalGroup.position.set(-4.15, 0, 0);
    this.rivalModel = createCarModel(rivalCar, rivalBuild, { cockpit: false, paintColor: 0x21d9c2, accentColor: 0xff2d9a });
    this.rivalGroup.add(this.rivalModel.group);
    this.scene.add(this.rivalGroup);
    this.rivalModel.group.rotation.y = Math.PI;

    // Physics state.
    this.phase = 'prestage';
    this.phaseClock = 0;
    this.raceTime = 0;
    this.treeStep = -1;
    this.treeStarted = false;
    this.greenAt = null;
    this.reaction = null;
    this.falseStart = false;
    this.penalty = 0;
    this.speed = 0;
    this.travel = 0;
    this.gear = 0;
    this.rpm = car.idle;
    this.clutch = 1;
    this.clutchPedal = 1;
    this.throttle = 0;
    this.brake = 0;
    this.steer = 0;
    this.steerTarget = 0;
    this.boost = 0;
    this.boostActive = 0;
    this.nitro = 0;
    this.tireHeat = 0.12;
    this.slip = 0;
    this.rpmLimiter = false;
    this.shiftPenalty = 0;
    this.perfectShifts = 0;
    this.topSpeed = 0;
    this.lastGear = 0;
    this.engineTemp = 0;
    this.cameraShake = 0;
    this.messageCooldown = 0;
    this.lastHud = 0;
    this.finished = false;
    this.resultShown = false;
    this.resultDelay = 0;
    this.finishTime = null;
    this.rivalFinishTime = null;
    this.disposed = false;
    this.raceElapsed = 0;
    this.input = { throttle: 0, brake: 0, clutch: 0, steerLeft: 0, steerRight: 0 };
    this._acc = 0;
    this._clock = 0;
    this._rivalTimeAcc = 0;
    this._rivalMoved = false;
    this._lastBeep = -1;
    this._smokeTimer = 0;
    this._messages = [];

    this.setupRivalPlan();
    this.setupEffects();
    this.bindHud();

    this.audio?.startEngine(this.stats.sound);
    this.onMessage('HOLD CLUTCH • SELECT 1ST • BUILD BOOST', 'hint', 3.8);
  }

  setupRivalPlan() {
    // The rival's pace is calibrated to the player's build so every duel is close,
    // but higher-skill rivals get a smaller time multiplier.
    const base = estimateTime(this.stats.power, this.stats.weight, this.distance.meters);
    const skill = this.rivalDef.skill;
    const multiplier = clamp(1.065 - (skill - 0.72) * 0.25, 0.82, 1.1) * (this.event?.difficultyMult || 1);
    this.rivalReaction = clamp(0.12 + (1 - skill) * 0.38 + Math.random() * 0.08, 0.14, 0.55);
    const target = base * multiplier + (Math.random() - 0.5) * 0.12;
    this.rivalTime = Math.max(5, target);
    this.rivalDriveTime = Math.max(3.2, this.rivalTime - this.rivalReaction);
    const vmax = 58 + this.stats.power * 0.17;
    let lo = 1, hi = 38;
    for (let i = 0; i < 28; i++) {
      const mid = (lo + hi) / 2;
      const t = this.simulateRival(mid, vmax, this.rivalDriveTime);
      if (t.time < this.distance.meters) lo = mid; else hi = mid;
    }
    this.rivalAccel = (lo + hi) / 2;
    this.rivalVmax = vmax;
    this.rivalStart = 0;
    this.rivalSpeed = 0;
    this.rivalDriveElapsed = -this.rivalReaction;
    this.rivalCrossed = false;
    this.rivalActualTime = null;
  }

  simulateRival(a0, vmax, seconds) {
    let v = 0, d = 0;
    const dt = 1 / 60;
    let t = 0;
    while (t < seconds && d < this.distance.meters) {
      const a = a0 * clamp(1 - Math.pow(v / vmax, 2.1), 0.03, 1);
      v += a * dt;
      d += v * dt;
      t += dt;
    }
    return { time: t, speed: v, dist: d };
  }

  setupEffects() {
    const streakGeo = new THREE.BufferGeometry();
    const count = 72;
    const arr = new Float32Array(count * 6);
    this.streaks = [];
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const radius = 1.8 + Math.random() * 5.5;
      const x = Math.cos(a) * radius;
      const y = Math.sin(a) * radius * 0.6;
      const z = -4 - Math.random() * 24;
      const len = 1.5 + Math.random() * 4;
      arr[i * 6] = x; arr[i * 6 + 1] = y; arr[i * 6 + 2] = z;
      arr[i * 6 + 3] = x; arr[i * 6 + 4] = y; arr[i * 6 + 5] = z; // length is animated via attributes
      this.streaks.push({ x, y, z, len, speed: 18 + Math.random() * 26 });
    }
    streakGeo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    this.streakMat = new THREE.LineBasicMaterial({ color: 0xe5f7ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false });
    this.streakLines = new THREE.LineSegments(streakGeo, this.streakMat);
    this.streakLines.frustumCulled = false;
    this.streakLines.renderOrder = 99;
    this.camera.add(this.streakLines);
    this.streakPos = arr;

    const smokeTex = radialTexture(0xd9d9d9);
    this.smoke = [];
    for (let i = 0; i < 26; i++) {
      const m = new THREE.SpriteMaterial({ map: smokeTex, color: 0xebe5db, transparent: true, opacity: 0, depthWrite: false, blending: THREE.NormalBlending });
      const s = new THREE.Sprite(m);
      s.visible = false;
      this.scene.add(s);
      this.smoke.push({ sprite: s, life: 0, max: 1, vx: 0, vy: 0, vz: 0 });
    }
    this.smokeIndex = 0;

    // Under-car glow pool flicker when nitro is used.
    this.nitroLight = new THREE.PointLight(0x44ffe0, 0, 14, 2);
    this.nitroLight.position.set(4.15, 0.8, -1.5);
    this.scene.add(this.nitroLight);

    // A small red flash at launch.
    this.flashLight = new THREE.PointLight(0xff3d6a, 0, 10, 2);
    this.flashLight.position.set(4.15, 1.4, -1);
    this.scene.add(this.flashLight);
  }

  bindHud() {
    this.hud = {
      speedKph: 0, rpm: this.rpm, gear: 0, phase: 'prestage',
      time: 0, distance: 0, progress: 0, rivalGap: 0,
      throttle: 0, brake: 0, clutch: 1, boost: 0, tireHeat: 0.12,
      slip: 0, nitro: 0, reaction: null, penalty: 0, treeStep: -1,
      message: '', track: this.track, playerName: this.car.short,
      rivalName: this.rivalDef.name, rivalCar: this.rivalDef.car,
      falseStart: false, finished: false, position: 1
    };
  }

  requestGear(g) {
    if (this.finished) return;
    if (g === this.gear) return;
    if (g === 'N') {
      this.gear = 0;
      this.audio?.shift(false);
      this.onMessage('NEUTRAL', 'info', 0.8);
      return;
    }
    if (g === 'R') {
      if (this.speed > 1.5) {
        this.audio?.grind();
        this.onMessage('TOO FAST FOR REVERSE', 'bad', 1.2);
        return;
      }
      if (this.clutchPedal < 0.55) {
        this.audio?.grind();
        this.onMessage('PRESS THE CLUTCH', 'bad', 1.2);
        return;
      }
      this.gear = -1;
      this.audio?.shift();
      return;
    }
    const n = Number(g);
    if (!Number.isInteger(n) || n < 1 || n > this.car.gears.length) return;
    if (this.clutchPedal < 0.55) {
      this.audio?.grind();
      this.cameraShake = Math.max(this.cameraShake, 0.16);
      this.onMessage('GRIND! PRESS CLUTCH TO SHIFT', 'bad', 1.4);
      return;
    }
    const before = this.gear;
    const rpmBefore = this.rpm;
    const ratio = this.car.gears[n - 1];
    const expected = (Math.abs(this.speed) / (this.car.wheels.size || 0.33)) * 60 / (Math.PI * 2) * ratio * this.car.finalDrive;
    this.gear = n;
    this.shiftPenalty = 0;
    let perfect = false;
    if (before > 0 && n > before && rpmBefore > this.stats.redline * 0.82 && expected < this.stats.redline) {
      perfect = true;
      this.perfectShifts++;
      this.nitro = Math.min(100, this.nitro + 34);
      this.shiftPenalty = -1.25;
      this.cameraShake = Math.max(this.cameraShake, 0.07);
      this.audio?.chime([660, 990], 0.055);
      this.onMessage('PERFECT SHIFT  +NITRO', 'perfect', 1.4);
      this.flashLight.intensity = 8;
    } else if (n < before && expected > this.stats.redline) {
      this.shiftPenalty = 2.0;
      this.onMessage('OVERREV! EASE IT IN', 'bad', 1.2);
      this.audio?.grind();
    } else if (before > 0 && Math.abs(rpmBefore - expected) > 2200) {
      this.shiftPenalty = 0.75;
      this.onMessage('CLUTCH BUMP', 'warn', 0.9);
    } else {
      this.onMessage(n > 0 ? `${n}${n === 1 ? 'ST' : n === 2 ? 'ND' : n === 3 ? 'RD' : 'TH'} GEAR` : 'NEUTRAL', 'info', 0.7);
    }
    this.audio?.shift(perfect);
    if (n > 0) this.audio?.backfire();
    this.cameraShake = Math.max(this.cameraShake, 0.04);
    this.lastGear = before;
  }

  activateNitro() {
    if (this.phase !== 'running' || this.finished) return false;
    if (this.nitro < 100) {
      this.onMessage('PERFECT SHIFTS CHARGE NITRO', 'warn', 1.0);
      return false;
    }
    this.nitro = 0;
    this.boostActive = 2.2;
    this.flashLight.intensity = 20;
    this.audio?.chime([440, 660, 880], 0.06);
    this.onMessage('NEON BOOST!', 'perfect', 1.3);
    return true;
  }

  setInput(name, value) {
    if (name in this.input) this.input[name] = value;
  }

  update(dtReal) {
    if (this.disposed) return;
    dtReal = Math.min(0.06, dtReal);
    this._clock += dtReal;
    this.phaseClock += dtReal;
    this.messageCooldown = Math.max(0, this.messageCooldown - dtReal);
    this.cameraShake = Math.max(0, this.cameraShake - dtReal * 0.5);
    this.flashLight.intensity = Math.max(0, this.flashLight.intensity - dtReal * 30);
    if (this.boostActive > 0) this.boostActive = Math.max(0, this.boostActive - dtReal);
    const smooth = Math.min(1, dtReal * 8);
    this.throttle += ((this.input.throttle || 0) - this.throttle) * smooth;
    this.brake += ((this.input.brake || 0) - this.brake) * smooth;
    this.clutchPedal += ((this.input.clutch || 0) - this.clutchPedal) * Math.min(1, dtReal * 8);
    this.steerTarget = (this.input.steerRight || 0) - (this.input.steerLeft || 0);

    // Start sequence.
    if (this.phase === 'prestage') {
      if (this.phaseClock > 0.9) {
        this.phase = 'tree';
        this.phaseClock = 0;
        this.treeStarted = true;
        this.treeStep = 0;
        this.env.setStartLights(0);
        this.audio?.beep(false);
      }
    } else if (this.phase === 'tree') {
      const steps = [0.52, 1.04, 1.56];
      const greenDelay = 2.08 + Math.random() * 0.3;
      let step = -1;
      if (this.phaseClock > greenDelay) step = 3;
      else if (this.phaseClock > steps[2]) step = 2;
      else if (this.phaseClock > steps[1]) step = 1;
      else if (this.phaseClock > steps[0]) step = 0;
      if (step !== this.treeStep) {
        this.treeStep = step;
        this.env.setStartLights(step);
        if (step < 3) this.audio?.beep(false);
      }
      if (step === 3 && this.phase !== 'running') {
        this.phase = 'running';
        this.greenAt = this.phaseClock;
        this.raceTime = 0;
        this.audio?.beep(true);
        this.audio?.crowd(0.15);
        this.onMessage('GO! GO! GO!', 'go', 1.0);
        this.flashLight.intensity = 5;
      }
    }

    if (this.phase === 'running' || this.phase === 'finished') {
      this._acc += dtReal;
      let loops = 0;
      while (this._acc >= FIXED && loops < 5) {
        this.fixedStep(FIXED);
        this._acc -= FIXED;
        loops++;
      }
      this.raceElapsed += dtReal;
    } else {
      // Engine can rev during staging while the car remains stationary.
      this.updateEngine(dtReal, false);
      this.updateCarVisuals(dtReal);
    }

    if (this.phase === 'running') {
      if (this.speed > 0.55 && this.reaction === null) this.reaction = this.raceTime;
      if (this.travel >= this.distance.meters && !this.finished) this.finishRace();
      if (!this.falseStart && this.phase === 'tree' && this.speed > 0.4) {
        this.falseStart = true;
        this.penalty = 1.0;
        this.onMessage('JUMP START  +1.00s', 'bad', 2);
      }
    }

    // Rival movement.
    if (this.phase === 'running' || this.phase === 'finished') {
      this.updateRival(dtReal);
    }

    this.updateCamera(dtReal);
    this.updateEffects(dtReal);
    this.env.update(dtReal, this._clock, this.speed);
    this.playerModel.spin((this.speed / (this.car.wheels.size || 0.33)) * dtReal * (this.slip > 0.1 ? 1.8 : 1));
    this.rivalModel.spin((this.rivalSpeed / (this.car.wheels.size || 0.33)) * dtReal);
    this.playerModel.setBrake(this.brake > 0.1 || this.phase === 'prestage' || this.phase === 'tree');
    this.updateAudio(dtReal);

    if (this.finished) {
      this.resultDelay += dtReal;
      if (!this.resultShown && this.resultDelay > 1.6) {
        this.resultShown = true;
        this.showResult();
      }
    }

    if (this.phase === 'running') {
      if (!this.falseStart && this.treeStep >= 0 && this.phaseClock < 2.08 && this.speed > 0.4) {
        this.falseStart = true;
        this.penalty = 1.0;
      }
    }

    // HUD at 20 fps.
    this.lastHud += dtReal;
    if (this.lastHud > 0.05) {
      this.lastHud = 0;
      this.emitHud();
    }
  }

  fixedStep(dt) {
    const stats = this.stats;
    if (this.phase === 'tree' && this.speed > 0.4 && !this.falseStart) {
      this.falseStart = true; this.penalty = 1.0;
      this.onMessage('JUMP START  +1.00s', 'bad', 1.8);
    }
    this.raceTime += dt;

    // aerodynamic and rolling resistance
    const drag = 0.00038 * this.speed * this.speed;
    const rolling = this.speed > 0.1 ? 0.16 : 0;
    const brakeForce = this.brake * 8.5;
    const gear = this.gear;
    const gearRatio = gear > 0 ? this.car.gears[gear - 1] : gear === -1 ? 3.2 : 0;
    const wheelCircum = 2 * Math.PI * (this.car.wheels.size || 0.33);
    const engineDriveRpm = gear > 0 ? (Math.abs(this.speed) / wheelCircum) * 60 * gearRatio * this.car.finalDrive : gear === -1 ? Math.abs(this.speed) / wheelCircum * 60 * 3.2 * this.car.finalDrive : 0;

    // Clutch engagement.
    this.clutch = clamp(1 - this.clutchPedal, 0, 1);
    const clutchEngaged = gear !== 0 ? this.clutch : 0;

    const limiter = this.rpm >= stats.redline;
    this.rpmLimiter = limiter;
    const freeTarget = stats.redline * 0.89;
    const freeRpm = stats.idle + this.throttle * Math.max(800, freeTarget - stats.idle);
    let targetRpm;
    if (gear === 0 || this.clutchPedal > 0.72) {
      targetRpm = limiter ? stats.redline * 0.97 : freeRpm;
    } else {
      targetRpm = lerp(freeRpm, Math.max(stats.idle * 0.8, engineDriveRpm), Math.pow(this.clutch, 1.3));
      if (this.speed < 1.2 && this.throttle > 0.5) targetRpm = Math.max(targetRpm, freeRpm * 0.9);
    }

    const isBurnout = gear >= 1 && this.brake > 0.55 && this.throttle > 0.45 && this.speed < 2.2;
    if (isBurnout) targetRpm = stats.idle + this.throttle * (stats.redline * 0.7);
    const rpmRate = gear === 0 || this.clutchPedal > 0.72 || isBurnout ? 6.5 : 4.0 + this.clutch * 7;
    this.rpm += (targetRpm - this.rpm) * Math.min(1, dt * rpmRate);
    if (this.rpm > stats.redline) {
      this.rpm = stats.redline;
      if (this._clock % 0.2 < dt) this.cameraShake = Math.max(this.cameraShake, 0.04);
    }
    if (this.rpm < 0) this.rpm = 0;

    // Torque curve and boost.
    const normalized = clamp((this.rpm - 700) / (stats.redline - 700), 0, 1);
    const curve = clamp(0.44 + Math.sin(Math.min(1, normalized) * Math.PI * 0.93) * 0.92 + normalized * 0.18, 0.18, 1.25);
    const boosting = this.boostActive > 0 ? 1.34 : 1;
    const torque = stats.torque * curve * this.throttle * (1 + this.boost * 0.72) * boosting;
    const driveForce = torque * gearRatio * this.car.finalDrive * 0.91 / (this.car.wheels.size || 0.33);
    let accel = driveForce / stats.weight * clutchEngaged;
    // Engine braking / over-rev drag.
    if (this.throttle < 0.08 && gear !== 0) accel -= (gearRatio * this.car.finalDrive * 22 / stats.weight) * clutchEngaged;
    // Traction limit. AWD launches hardest, RWD spins, FWD fights for grip.
    const tractionFactor = this.car.drivetrain === 'AWD' ? 1.22 : this.car.drivetrain === 'RWD' ? 0.78 : 0.63;
    const grip = stats.grip * (0.9 + this.tireHeat * 0.2);
    const maxTraction = stats.weight * 9.81 * grip * tractionFactor;
    let slip = 0;
    if (driveForce > maxTraction && this.speed < 65) {
      slip = Math.min(1, (driveForce - maxTraction) / Math.max(1, maxTraction));
      accel = (maxTraction / stats.weight) * (1 - slip * 0.34) * clutchEngaged;
    }
    if (isBurnout) {
      slip = Math.max(slip, this.throttle * 0.85);
      accel = 0;
      this.tireHeat = Math.min(1, this.tireHeat + dt * 0.23 * this.throttle);
      this.boost = Math.min(1.3, this.boost + dt * (0.45 + this.throttle * 0.2));
    }
    if (slip > 0.12) this.tireHeat = Math.min(1, this.tireHeat + dt * slip * 0.06);
    this.tireHeat = Math.max(0.08, this.tireHeat - dt * 0.012);
    this.slip = slip;
    if (this.shiftPenalty > 0) {
      accel *= 0.58;
      this.shiftPenalty -= dt;
    } else if (this.shiftPenalty < 0) {
      accel *= 1.11;
      this.shiftPenalty += dt;
    }
    if (this.phase === 'tree' && this.falseStart) accel *= 0.45;
    accel -= drag + rolling + brakeForce;
    if (this.brake > 0.9 && this.speed < 0.05) accel = Math.max(0, accel);
    this.speed += accel * dt;
    if (this.speed < 0) this.speed = 0;
    if (this.phase !== 'running' && this.phase !== 'finished') {
      // During the tree we allow creeping so a jump start has consequences, but
      // not automatic launch. That still requires the player's clutch + throttle.
      if (this.speed < 0.02) this.speed = 0;
    }
    const ds = this.speed * dt;
    this.travel += ds;
    this.lastDs = ds;
    this.playerGroup.position.z = -this.travel;
    this.playerGroup.position.x = clamp(this.playerGroup.position.x + this.steer * dt * 1.5, 1.4, 8.25);
    this.steer += (this.steerTarget - this.steer) * Math.min(1, dt * 6);
    this.topSpeed = Math.max(this.topSpeed, this.speed);
    this.boost = Math.max(0, this.boost - dt * (this.throttle > 0.2 ? 0.11 : 0.55));

    if (this.phase === 'tree' && this.speed > 0.4) {
      this.falseStart = true;
      if (!this.penalty) this.penalty = 1.0;
    }
    this.engineTemp += dt * (0.2 + this.rpm / stats.redline);
  }

  updateEngine(dt, driving) {
    const stats = this.stats;
    const freeTarget = stats.idle + this.throttle * (stats.redline * 0.85 - stats.idle);
    const target = this.gear === 0 || this.clutchPedal > 0.72 ? freeTarget : Math.max(stats.idle, freeTarget * 0.7);
    this.rpm += (target - this.rpm) * Math.min(1, dt * 4.5);
    this.boost = Math.min(1.2, Math.max(0, this.boost + (this.throttle * 0.8 - this.boost * 0.7) * dt));
    this.playerGroup.position.z = -this.travel;
  }

  updateAudio(dt) {
    if (!this.audio) return;
    this._audioTick = (this._audioTick || 0) + dt;
    if (this._audioTick < 0.03) return;
    this._audioTick = 0;
    this.audio.updateEngine({
      rpm: this.rpm, throttle: this.throttle, clutch: this.clutchPedal,
      speed: this.speed * 3.6, boost: this.boost, boostTarget: this.boost,
      slip: this.slip + (this.brake > 0.6 && this.speed < 1 ? this.throttle * 0.5 : 0),
      gear: this.gear, stalled: false, limiter: this.rpmLimiter
    });
  }

  updateRival(dt) {
    if (this.phase !== 'running' && this.phase !== 'finished') return;
    this.rivalDriveElapsed += dt;
    if (this.rivalDriveElapsed < 0) {
      this.rivalGroup.position.z = 0;
      this.rivalSpeed = 0;
      return;
    }
    if (this.rivalCrossed) {
      this.rivalGroup.position.z = -this.distance.meters - Math.min(45, (this.rivalDriveElapsed - this.rivalDriveTime) * 18);
      return;
    }
    let v = this.rivalSpeed;
    const a = this.rivalAccel * clamp(1 - Math.pow(v / this.rivalVmax, 2.1), 0.03, 1);
    v += a * dt;
    this.rivalSpeed = v;
    this.rivalGroup.position.z -= v * dt;
    this.rivalGroup.position.x = -4.15 + Math.sin(this.rivalDriveElapsed * 1.3) * 0.05;
    this.rivalModel.spin(v / (this.car.wheels.size || 0.33) * dt);
    if (-this.rivalGroup.position.z >= this.distance.meters) {
      this.rivalCrossed = true;
      this.rivalActualTime = this.rivalTime;
    }
    if (this.rivalDriveElapsed > 0.4) this.rivalModel.group.rotation.z = Math.sin(this.rivalDriveElapsed * 15) * 0.006;
  }

  updateCarVisuals(dt) {
    this.playerModel.spin((this.speed / (this.car.wheels.size || 0.33)) * dt);
    this.playerGroup.position.z = -this.travel;
  }

  updateCamera(dt) {
    const group = this.playerGroup;
    const baseYaw = 0;
    const steerYaw = this.steer * 0.045;
    const shakeAmount = (this.rpm / this.stats.redline) * 0.003 + this.speed * 0.00015 + this.cameraShake;
    const t = this._clock;
    const shakeX = (Math.sin(t * 63) + Math.sin(t * 37 + 1.3)) * shakeAmount;
    const shakeY = (Math.sin(t * 91 + 2.1) + Math.sin(t * 43)) * shakeAmount * 1.4;
    const accelKick = this.phase === 'running' && this.speed < 3 && this.throttle > 0.5 ? 0.006 : 0;
    const targetX = group.position.x + 0.38 + shakeX;
    const targetY = 1.28 + shakeY - Math.max(0, this.speed) * 0.0004;
    const targetZ = group.position.z + 0.1 - Math.max(0, this.speed) * 0.00008;
    this.camera.position.x = lerp(this.camera.position.x, targetX, Math.min(1, dt * 14));
    this.camera.position.y = lerp(this.camera.position.y, targetY, Math.min(1, dt * 14));
    this.camera.position.z = lerp(this.camera.position.z, targetZ, Math.min(1, dt * 18));
    this.camera.rotation.y = lerp(this.camera.rotation.y, baseYaw + steerYaw + shakeX * 0.02, Math.min(1, dt * 8));
    this.camera.rotation.x = lerp(this.camera.rotation.x, -0.065 + shakeY * 0.02 + accelKick, Math.min(1, dt * 10));
    this.camera.rotation.z = lerp(this.camera.rotation.z, -this.steer * 0.018 + shakeX * 0.04, Math.min(1, dt * 8));
    this.camera.fov = lerp(this.camera.fov, 70 + Math.min(12, this.speed * 0.11) + (this.boostActive > 0 ? 4 : 0), Math.min(1, dt * 2.5));
    this.camera.updateProjectionMatrix();
    this.playerModel.group.rotation.y = -this.steer * 0.012;
    this.playerModel.group.rotation.z = -this.steer * 0.01;
    this.playerModel.group.position.y = -Math.max(0, this.cameraShake) * 0.03;
    this.playerModel.group.rotation.x = this.speed < 1 && this.throttle > 0.6 ? -0.007 : 0;
    // Cockpit updates every frame.
    this.playerModel.update(dt, {
      rpm: this.rpm, speed: this.speed, gear: this.gear, steering: this.steer,
      throttle: this.throttle, brake: this.brake, clutch: this.clutchPedal,
      boost: this.boost, time: fmtTime(this.raceTime), phase: this.phase === 'running' ? 'RACING' : this.phase.toUpperCase(),
      redline: this.stats.redline, rivalText: `RIVAL ${this.rivalDef.name}  ${this.getGapText()}`
    });
    this.nitroLight.intensity = this.boostActive > 0 ? 18 + Math.sin(t * 30) * 6 : 0;
    this.nitroLight.position.set(group.position.x, 0.8, group.position.z - 1.5);
  }

  getGapText() {
    if (this.phase !== 'running' && this.phase !== 'finished') return '--';
    const diff = this.travel - (-this.rivalGroup.position.z);
    if (!this.rivalCrossed && this.rivalDriveElapsed > 0) {
      if (Math.abs(diff) < 0.5) return 'DOOR TO DOOR';
      const sec = Math.abs(diff) / Math.max(8, this.speed);
      return diff > 0 ? `+${sec.toFixed(2)}s` : `-${sec.toFixed(2)}s`;
    }
    return this.rivalCrossed ? (this.finishTime && this.finishTime < this.rivalTime ? 'AHEAD' : 'BEHIND') : '--';
  }

  emitHud() {
    const h = this.hud;
    h.speedKph = this.speed * 3.6;
    h.rpm = this.rpm;
    h.gear = this.gear;
    h.phase = this.phase;
    h.time = this.raceTime;
    h.distance = this.travel;
    h.progress = clamp(this.travel / this.distance.meters, 0, 1);
    h.rivalProgress = clamp((-this.rivalGroup.position.z) / this.distance.meters, 0, 1);
    h.rivalGap = this.travel - (-this.rivalGroup.position.z);
    h.throttle = this.throttle;
    h.brake = this.brake;
    h.clutch = this.clutchPedal;
    h.boost = this.boost;
    h.tireHeat = this.tireHeat;
    h.slip = this.slip;
    h.nitro = this.nitro;
    h.reaction = this.reaction;
    h.penalty = this.penalty;
    h.treeStep = this.treeStep;
    h.falseStart = this.falseStart;
    h.finished = this.finished;
    h.gapText = this.getGapText();
    h.boostActive = this.boostActive;
    h.position = this.travel >= (-this.rivalGroup.position.z) ? 1 : 2;
    this.onHud(h);
  }

  finishRace() {
    if (this.finished) return;
    this.finished = true;
    this.phase = 'finished';
    this.finishTime = this.raceTime + this.penalty;
    this.resultDelay = 0;
    this.audio?.crowd(0.2);
    this.onMessage(this.finishTime < this.rivalTime ? 'WINNER!' : 'FINISH', this.finishTime < this.rivalTime ? 'perfect' : 'info', 1.5);
  }

  showResult() {
    const won = this.finishTime < this.rivalTime;
    const gap = Math.abs(this.rivalTime - this.finishTime);
    const result = {
      won,
      playerTime: this.finishTime,
      rawTime: this.raceTime,
      rivalTime: this.rivalTime,
      reaction: this.reaction,
      topSpeed: this.topSpeed * 3.6,
      perfectShifts: this.perfectShifts,
      penalty: this.penalty,
      gap,
      distance: this.distance.id,
      meters: this.distance.meters,
      track: this.track,
      car: this.car,
      rival: this.rivalDef,
      event: this.event,
      falseStart: this.falseStart,
      timeText: fmtTime(this.finishTime),
      rivalTimeText: fmtTime(this.rivalTime)
    };
    this.onFinish(result);
  }

  dispose() {
    this.disposed = true;
    this.audio?.stopEngine();
    this.scene.traverse(o => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach(m => { m.map?.dispose?.(); m.dispose?.(); });
        else { o.material.map?.dispose?.(); o.material.dispose?.(); }
      }
    });
  }
}

