184:   const disc = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.54, radius * 0.54, 0.035, 18), metal(0x5a5f69, 0.55));
185:   disc.rotation.z = Math.PI / 2;
186:   g.add(disc);
187:   const caliper = rounded(0.035, 0.16, 0.13, 0.02, new THREE.MeshBasicMaterial({ color: 0xffc62b }));
188:   caliper.position.set(side * 0.13, 0.06, 0.13);
189:   g.add(caliper);
190:   const spokeCount = style.kind === 'six' ? 6 : style.kind === 'mesh' ? 8 : style.kind === 'blade' ? 3 : style.kind === 'star' ? 5 : 6;
191:   for (let i = 0; i < spokeCount; i++) {
192:     const angle = (i / spokeCount) * Math.PI * 2;
193:     const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.032, radius * 0.62, style.kind === 'mesh' ? 0.038 : 0.06), metal(style.rim, 0.3));
194:     spoke.position.set(side * (width * 0.37), Math.cos(angle) * radius * 0.28, Math.sin(angle) * radius * 0.28);
195:     spoke.rotation.x = angle;
196:     g.add(spoke);
197:   }
198:   if (style.kind === 'dish') {
199:     const dish = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.67, radius * 0.58, 0.11, 18), metal(style.rim, 0.15));
200:     dish.rotation.z = Math.PI / 2;
201:     dish.position.x = side * 0.07;
202:     g.add(dish);
203:   }
204:   const cap = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.17, radius * 0.17, 0.03, 14), metal(0x25272d, 0.2));
205:   cap.rotation.z = Math.PI / 2;
206:   cap.position.x = side * (width * 0.4);
207:   g.add(cap);
208:   return g;
209: }
