481:   function drawGauge(rpm, speed, gear, boost) {
482:     const x = gaugeCtx;
483:     x.clearRect(0, 0, 512, 256);
484:     const bg = x.createLinearGradient(0, 0, 0, 256);
485:     bg.addColorStop(0, '#15151c'); bg.addColorStop(1, '#050509');
486:     x.fillStyle = bg; x.fillRect(0, 0, 512, 256);
487:     // twin round gauges
488:     const cx1 = 116, cx2 = 262, cy = 134;
489:     const maxRpm = 9000;
490:     for (const [cx, label] of [[cx1, 'RPM'], [cx2, 'KM/H']]) {
491:       x.beginPath(); x.arc(cx, cy, 86, 0, Math.PI * 2); x.fillStyle = '#0d0d13'; x.fill();
492:       x.strokeStyle = '#4b4a57'; x.lineWidth = 8; x.stroke();
493:       x.beginPath(); x.arc(cx, cy, 72, Math.PI * 0.75, Math.PI * 2.25); x.strokeStyle = '#ff365b'; x.lineWidth = 3; x.stroke();
494:       x.fillStyle = '#f2eedf'; x.font = '700 18px Rajdhani, sans-serif'; x.textAlign = 'center'; x.fillText(label, cx, 221);
495:     }
496:     // rpm ticks
497:     for (let i = 0; i <= 8; i++) {
498:       const a = Math.PI * 0.75 + (i / 8) * Math.PI * 1.5;
499:       x.beginPath();
500:       x.moveTo(cx1 + Math.cos(a) * 64, cy + Math.sin(a) * 64);
501:       x.lineTo(cx1 + Math.cos(a) * 76, cy + Math.sin(a) * 76);
502:       x.strokeStyle = i > 6 ? '#ff365b' : '#82818d'; x.lineWidth = i % 2 === 0 ? 4 : 2; x.stroke();
503:       if (i % 2 === 0) {
504:         x.fillStyle = i > 6 ? '#ff365b' : '#aaa8b3'; x.font = '700 14px Rajdhani';
505:         x.fillText(String(i), cx1 + Math.cos(a) * 48, cy + Math.sin(a) * 48 + 5);
506:       }
507:     }
508:     const rpmA = Math.PI * 0.75 + Math.min(1, rpm / maxRpm) * Math.PI * 1.5;
509:     x.beginPath(); x.moveTo(cx1, cy); x.lineTo(cx1 + Math.cos(rpmA) * 62, cy + Math.sin(rpmA) * 62);
510:     x.strokeStyle = rpm > maxRpm * 0.9 ? '#ff284e' : '#f4be3e'; x.lineWidth = 5; x.stroke();
511:     x.beginPath(); x.arc(cx1, cy, 8, 0, 7); x.fillStyle = '#f4be3e'; x.fill();
512:     x.fillStyle = '#f3eee0'; x.font = '900 39px Rajdhani'; x.textAlign = 'center';
513:     x.fillText(String(Math.round(rpm)).padStart(4, '0'), cx1, 191);
514:     // speed gauge needle
515:     const speedA = Math.PI * 0.75 + Math.min(1, speed / 320) * Math.PI * 1.5;
516:     x.beginPath(); x.moveTo(cx2, cy); x.lineTo(cx2 + Math.cos(speedA) * 62, cy + Math.sin(speedA) * 62);
517:     x.strokeStyle = '#34ebd0'; x.lineWidth = 5; x.stroke();
518:     x.beginPath(); x.arc(cx2, cy, 8, 0, 7); x.fillStyle = '#34ebd0'; x.fill();
519:     x.fillStyle = '#f3eee0'; x.font = '900 39px Rajdhani'; x.textAlign = 'center';
520:     x.fillText(String(Math.round(speed)), cx2, 191);
521:     x.fillStyle = '#858391'; x.font = '600 13px Rajdhani'; x.fillText('GEAR', 400, 80);
522:     x.fillStyle = '#fff8e5'; x.font = '900 33px Bebas Neue'; x.fillText(gear === 0 ? 'N' : gear === -1 ? 'R' : String(gear), 400, 112);
523:     x.fillStyle = '#858391'; x.font = '600 13px Rajdhani'; x.fillText('BOOST', 400, 142);
524:     x.fillStyle = boost > 0.1 ? '#ff5e94' : '#565463'; x.fillRect(400, 152, 78, 8);
525:     x.fillStyle = '#ff5e94'; x.fillRect(400, 152, 78 * Math.min(1, boost * 1.7), 8);
526:     // brand ticker
527:     x.fillStyle = '#ff365b'; x.font = '700 13px Rajdhani'; x.textAlign = 'left'; x.fillText('TOKYO REDLINE // STREET SPEC', 300, 234);
528:     gaugeTex.needsUpdate = true;
529:   }
