125:   setupRivalPlan() {
126:     // The rival's pace is calibrated to the player's build so every duel is close,
127:     // but higher-skill rivals get a smaller time multiplier.
128:     const base = estimateTime(this.stats.power, this.stats.weight, this.distance.meters);
129:     const skill = this.rivalDef.skill;
130:     const multiplier = clamp(1.065 - (skill - 0.72) * 0.25, 0.82, 1.1) * (this.event?.difficultyMult || 1);
131:     this.rivalReaction = clamp(0.12 + (1 - skill) * 0.38 + Math.random() * 0.08, 0.14, 0.55);
132:     const target = base * multiplier + (Math.random() - 0.5) * 0.12;
133:     this.rivalTime = Math.max(5, target);
134:     this.rivalDriveTime = Math.max(3.2, this.rivalTime - this.rivalReaction);
135:     const vmax = 58 + this.stats.power * 0.17;
136:     let lo = 1, hi = 38;
137:     for (let i = 0; i < 28; i++) {
138:       const mid = (lo + hi) / 2;
139:       const t = this.simulateRival(mid, vmax, this.rivalDriveTime);
140:       if (t.time < this.distance.meters) lo = mid; else hi = mid;
141:     }
142:     this.rivalAccel = (lo + hi) / 2;
143:     this.rivalVmax = vmax;
144:     this.rivalStart = 0;
145:     this.rivalSpeed = 0;
146:     this.rivalDriveElapsed = -this.rivalReaction;
147:     this.rivalCrossed = false;
148:     this.rivalActualTime = null;
149:   }
