151:   simulateRival(a0, vmax, seconds) {
152:     let v = 0, d = 0;
153:     const dt = 1 / 60;
154:     let t = 0;
155:     while (t < seconds && d < this.distance.meters) {
156:       const a = a0 * clamp(1 - Math.pow(v / vmax, 2.1), 0.03, 1);
157:       v += a * dt;
158:       d += v * dt;
159:       t += dt;
160:     }
161:     return { time: t, speed: v, dist: d };
162:   }
