222:   requestGear(g) {
223:     if (this.finished) return;
224:     if (g === this.gear) return;
225:     if (g === 'N') {
226:       this.gear = 0;
227:       this.audio?.shift(false);
228:       this.onMessage('NEUTRAL', 'info', 0.8);
229:       return;
230:     }
231:     if (g === 'R') {
232:       if (this.speed > 1.5) {
233:         this.audio?.grind();
234:         this.onMessage('TOO FAST FOR REVERSE', 'bad', 1.2);
235:         return;
236:       }
237:       if (this.clutchPedal < 0.55) {
238:         this.audio?.grind();
239:         this.onMessage('PRESS THE CLUTCH', 'bad', 1.2);
240:         return;
241:       }
242:       this.gear = -1;
243:       this.audio?.shift();
244:       return;
245:     }
246:     const n = Number(g);
247:     if (!Number.isInteger(n) || n < 1 || n > this.car.gears.length) return;
248:     if (this.clutchPedal < 0.55) {
249:       this.audio?.grind();
250:       this.cameraShake = Math.max(this.cameraShake, 0.16);
251:       this.onMessage('GRIND! PRESS CLUTCH TO SHIFT', 'bad', 1.4);
252:       return;
253:     }
254:     const before = this.gear;
255:     const rpmBefore = this.rpm;
256:     const ratio = this.car.gears[n - 1];
257:     const expected = (Math.abs(this.speed) / (this.car.wheels.size || 0.33)) * 60 / (Math.PI * 2) * ratio * this.car.finalDrive;
258:     this.gear = n;
259:     this.shiftPenalty = 0;
260:     let perfect = false;
261:     if (before > 0 && n > before && rpmBefore > this.stats.redline * 0.82 && expected < this.stats.redline) {
262:       perfect = true;
263:       this.perfectShifts++;
264:       this.nitro = Math.min(100, this.nitro + 34);
265:       this.shiftPenalty = -1.25;
266:       this.cameraShake = Math.max(this.cameraShake, 0.07);
267:       this.audio?.chime([660, 990], 0.055);
268:       this.onMessage('PERFECT SHIFT  +NITRO', 'perfect', 1.4);
269:       this.flashLight.intensity = 8;
270:     } else if (n < before && expected > this.stats.redline) {
271:       this.shiftPenalty = 2.0;
272:       this.onMessage('OVERREV! EASE IT IN', 'bad', 1.2);
273:       this.audio?.grind();
274:     } else if (before > 0 && Math.abs(rpmBefore - expected) > 2200) {
275:       this.shiftPenalty = 0.75;
276:       this.onMessage('CLUTCH BUMP', 'warn', 0.9);
277:     } else {
278:       this.onMessage(n > 0 ? `${n}${n === 1 ? 'ST' : n === 2 ? 'ND' : n === 3 ? 'RD' : 'TH'} GEAR` : 'NEUTRAL', 'info', 0.7);
279:     }
280:     this.audio?.shift(perfect);
281:     if (n > 0) this.audio?.backfire();
282:     this.cameraShake = Math.max(this.cameraShake, 0.04);
283:     this.lastGear = before;
284:   }
