304:   update(dtReal) {
305:     if (this.disposed) return;
306:     dtReal = Math.min(0.06, dtReal);
307:     this._clock += dtReal;
308:     this.phaseClock += dtReal;
309:     this.messageCooldown = Math.max(0, this.messageCooldown - dtReal);
310:     this.cameraShake = Math.max(0, this.cameraShake - dtReal * 0.5);
311:     this.flashLight.intensity = Math.max(0, this.flashLight.intensity - dtReal * 30);
312:     if (this.boostActive > 0) this.boostActive = Math.max(0, this.boostActive - dtReal);
313:     const smooth = Math.min(1, dtReal * 8);
314:     this.throttle += ((this.input.throttle || 0) - this.throttle) * smooth;
315:     this.brake += ((this.input.brake || 0) - this.brake) * smooth;
316:     this.clutchPedal += ((this.input.clutch || 0) - this.clutchPedal) * Math.min(1, dtReal * 8);
317:     this.steerTarget = (this.input.steerRight || 0) - (this.input.steerLeft || 0);
318: 
319:     // Start sequence.
320:     if (this.phase === 'prestage') {
321:       if (this.phaseClock > 0.9) {
322:         this.phase = 'tree';
323:         this.phaseClock = 0;
324:         this.treeStarted = true;
325:         this.treeStep = 0;
326:         this.env.setStartLights(0);
327:         this.audio?.beep(false);
328:       }
329:     } else if (this.phase === 'tree') {
330:       const steps = [0.52, 1.04, 1.56];
331:       const greenDelay = 2.08 + Math.random() * 0.3;
332:       let step = -1;
333:       if (this.phaseClock > greenDelay) step = 3;
334:       else if (this.phaseClock > steps[2]) step = 2;
335:       else if (this.phaseClock > steps[1]) step = 1;
336:       else if (this.phaseClock > steps[0]) step = 0;
337:       if (step !== this.treeStep) {
338:         this.treeStep = step;
339:         this.env.setStartLights(step);
340:         if (step < 3) this.audio?.beep(false);
341:       }
342:       if (step === 3 && this.phase !== 'running') {
343:         this.phase = 'running';
344:         this.greenAt = this.phaseClock;
345:         this.raceTime = 0;
346:         this.audio?.beep(true);
347:         this.audio?.crowd(0.15);
348:         this.onMessage('GO! GO! GO!', 'go', 1.0);
349:         this.flashLight.intensity = 5;
350:       }
351:     }
352: 
353:     if (this.phase === 'running' || this.phase === 'finished' || this.phase === 'tree') {
354:       this._acc += dtReal;
355:       let loops = 0;
356:       while (this._acc >= FIXED && loops < 5) {
357:         this.fixedStep(FIXED);
358:         this._acc -= FIXED;
359:         loops++;
360:       }
361:       this.raceElapsed += dtReal;
362:     } else {
363:       // Engine can rev during staging while the car remains stationary.
364:       this.updateEngine(dtReal, false);
365:       this.updateCarVisuals(dtReal);
366:     }
367: 
368:     if (this.phase === 'running') {
369:       if (this.speed > 0.55 && this.reaction === null) this.reaction = this.raceTime;
370:       if (this.travel >= this.distance.meters && !this.finished) this.finishRace();
371:     }
372: 
373:     // Rival movement.
374:     if (this.phase === 'running' || this.phase === 'finished') {
375:       this.updateRival(dtReal);
376:     }
377: 
378:     this.updateCamera(dtReal);
379:     this.updateEffects(dtReal);
380:     this.env.update(dtReal, this._clock, this.speed);
381:     this.playerModel.spin((this.speed / (this.car.wheels.size || 0.33)) * dtReal * (this.slip > 0.1 ? 1.8 : 1));
382:     this.rivalModel.spin((this.rivalSpeed / (this.car.wheels.size || 0.33)) * dtReal);
383:     this.playerModel.setBrake(this.brake > 0.1 || this.phase === 'prestage' || this.phase === 'tree');
384:     this.updateAudio(dtReal);
385: 
386:     if (this.finished) {
387:       this.resultDelay += dtReal;
388:       if (!this.resultShown && this.resultDelay > 1.6) {
389:         this.resultShown = true;
390:         this.showResult();
391:       }
392:     }
393: 
394:     // HUD at 20 fps.
395:     this.lastHud += dtReal;
396:     if (this.lastHud > 0.05) {
397:       this.lastHud = 0;
398:       this.emitHud();
399:     }
400:   }
401: 
402:   fixedStep(dt) {
403:     const stats = this.stats;
404:     if (this.phase === 'tree' && this.speed > 0.4 && !this.falseStart) {
405:       this.falseStart = true; this.penalty = 1.0;
406:       this.onMessage('JUMP START  +1.00s', 'bad', 1.8);
407:     }
408:     if (this.phase !== 'tree') this.raceTime += dt;
409: 
410:     // aerodynamic and rolling resistance
411:     const drag = 0.00038 * this.speed * this.speed;
412:     const rolling = this.speed > 0.1 ? 0.16 : 0;
413:     const brakeForce = this.brake * 8.5;
414:     const gear = this.gear;
415:     const gearRatio = gear > 0 ? this.car.gears[gear - 1] : gear === -1 ? 3.2 : 0;
416:     const wheelCircum = 2 * Math.PI * (this.car.wheels.size || 0.33);
417:     const engineDriveRpm = gear > 0 ? (Math.abs(this.speed) / wheelCircum) * 60 * gearRatio * this.car.finalDrive : gear === -1 ? Math.abs(this.speed) / wheelCircum * 60 * 3.2 * this.car.finalDrive : 0;
418: 
419:     // Clutch engagement.
420:     this.clutch = clamp(1 - this.clutchPedal, 0, 1);
421:     const clutchEngaged = gear !== 0 ? this.clutch : 0;
422: 
423:     const limiter = this.rpm >= stats.redline;
424:     this.rpmLimiter = limiter;
425:     const freeTarget = stats.redline * 0.89;
426:     const freeRpm = stats.idle + this.throttle * Math.max(800, freeTarget - stats.idle);
427:     let targetRpm;
428:     if (gear === 0 || this.clutchPedal > 0.72) {
429:       targetRpm = limiter ? stats.redline * 0.97 : freeRpm;
430:     } else {
431:       targetRpm = lerp(freeRpm, Math.max(stats.idle * 0.8, engineDriveRpm), Math.pow(this.clutch, 1.3));
432:       if (this.speed < 6.5 && this.throttle > 0.4) targetRpm = Math.max(targetRpm, freeRpm * (0.9 - Math.min(1, this.speed / 6.5) * 0.28));
433:     }
434: 
435:     const isBurnout = gear >= 1 && this.brake > 0.55 && this.throttle > 0.45 && this.speed < 2.2;
436:     if (isBurnout) targetRpm = stats.idle + this.throttle * (stats.redline * 0.7);
437:     const rpmRate = gear === 0 || this.clutchPedal > 0.72 || isBurnout ? 6.5 : 4.0 + this.clutch * 7;
438:     this.rpm += (targetRpm - this.rpm) * Math.min(1, dt * rpmRate);
439:     if (this.rpm > stats.redline) {
440:       this.rpm = stats.redline;
441:       if (this._clock % 0.2 < dt) this.cameraShake = Math.max(this.cameraShake, 0.04);
442:     }
443:     if (this.rpm < 0) this.rpm = 0;
444: 
445:     // Torque curve and boost.
446:     const normalized = clamp((this.rpm - 700) / (stats.redline - 700), 0, 1);
447:     const curve = clamp(0.44 + Math.sin(Math.min(1, normalized) * Math.PI * 0.93) * 0.92 + normalized * 0.18, 0.18, 1.25);
448:     const boosting = this.boostActive > 0 ? 1.34 : 1;
449:     const limiterCut = this.rpmLimiter ? (Math.floor(this._clock * 18) % 2 === 0 ? 0.08 : 1) : 1;
450:     const torque = stats.torque * curve * this.throttle * (1 + this.boost * 0.72) * boosting * limiterCut;
451:     const driveForce = torque * gearRatio * this.car.finalDrive * 0.91 / (this.car.wheels.size || 0.33);
452:     let accel = driveForce / stats.weight * clutchEngaged;
453:     // Engine braking / over-rev drag.
454:     if (this.throttle < 0.08 && gear !== 0) accel -= (gearRatio * this.car.finalDrive * 22 / stats.weight) * clutchEngaged;
455:     // Traction limit. AWD launches hardest, RWD spins, FWD fights for grip.
456:     const tractionFactor = this.car.drivetrain === 'AWD' ? 1.22 : this.car.drivetrain === 'RWD' ? 0.78 : 0.63;
457:     const grip = stats.grip * (0.9 + this.tireHeat * 0.2);
458:     const maxTraction = stats.weight * 9.81 * grip * tractionFactor;
459:     let slip = 0;
460:     if (driveForce > maxTraction && this.speed < 65) {
461:       slip = Math.min(1, (driveForce - maxTraction) / Math.max(1, maxTraction));
462:       accel = (maxTraction / stats.weight) * (1 - slip * 0.34) * clutchEngaged;
463:     }
464:     if (isBurnout) {
465:       slip = Math.max(slip, this.throttle * 0.85);
466:       accel = 0;
467:       this.tireHeat = Math.min(1, this.tireHeat + dt * 0.23 * this.throttle);
468:       this.boost = Math.min(1.3, this.boost + dt * (0.45 + this.throttle * 0.2));
469:     }
470:     if (slip > 0.12) this.tireHeat = Math.min(1, this.tireHeat + dt * slip * 0.06);
471:     this.tireHeat = Math.max(0.08, this.tireHeat - dt * 0.012);
472:     this.slip = slip;
473:     if (this.shiftPenalty > 0) {
474:       accel *= 0.58;
475:       this.shiftPenalty -= dt;
476:     } else if (this.shiftPenalty < 0) {
477:       accel *= 1.11;
478:       this.shiftPenalty += dt;
479:     }
480:     if (this.phase === 'tree' && this.falseStart) accel *= 0.45;
481:     accel -= drag + rolling + brakeForce;
482:     if (this.brake > 0.9 && this.speed < 0.05) accel = Math.max(0, accel);
483:     this.speed += accel * dt;
484:     if (this.speed < 0) this.speed = 0;
485:     if (this.phase !== 'running' && this.phase !== 'finished') {
486:       // During the tree we allow creeping so a jump start has consequences, but
487:       // not automatic launch. That still requires the player's clutch + throttle.
488:       if (this.speed < 0.02) this.speed = 0;
489:     }
490:     const ds = this.speed * dt;
491:     this.travel += ds;
492:     this.lastDs = ds;
493:     this.playerGroup.position.z = -this.travel;
494:     this.playerGroup.position.x = clamp(this.playerGroup.position.x + this.steer * dt * 1.5, 1.4, 8.25);
495:     this.steer += (this.steerTarget - this.steer) * Math.min(1, dt * 6);
496:     this.topSpeed = Math.max(this.topSpeed, this.speed);
497:     this.boost = Math.max(0, this.boost - dt * (this.throttle > 0.2 ? 0.11 : 0.55));
498: 
499:     if (this.phase === 'tree' && this.speed > 0.4) {
500:       this.falseStart = true;
501:       if (!this.penalty) this.penalty = 1.0;
502:     }
503:     this.engineTemp += dt * (0.2 + this.rpm / stats.redline);
504:   }
505: 
506:   updateEngine(dt, driving) {
507:     const stats = this.stats;
508:     const freeTarget = stats.idle + this.throttle * (stats.redline * 0.85 - stats.idle);
509:     const target = this.gear === 0 || this.clutchPedal > 0.72 ? freeTarget : Math.max(stats.idle, freeTarget * 0.7);
510:     this.rpm += (target - this.rpm) * Math.min(1, dt * 4.5);
511:     this.boost = Math.min(1.2, Math.max(0, this.boost + (this.throttle * 0.8 - this.boost * 0.7) * dt));
512:     this.playerGroup.position.z = -this.travel;
513:   }
514: 
515:   updateAudio(dt) {
516:     if (!this.audio) return;
517:     this._audioTick = (this._audioTick || 0) + dt;
518:     if (this._audioTick < 0.03) return;
519:     this._audioTick = 0;
