744:   disc.position.y = 0.09; group.add(disc);
745:   const rim = new THREE.Mesh(new THREE.TorusGeometry(3.4, 0.06, 8, 64), new THREE.MeshBasicMaterial({ color: 0xff2d9a, toneMapped: false }));
746:   rim.rotation.x = Math.PI / 2; rim.position.y = 0.19; group.add(rim);
747:   const rim2 = new THREE.Mesh(new THREE.TorusGeometry(4.7, 0.025, 8, 64), new THREE.MeshBasicMaterial({ color: 0x29f3e0, toneMapped: false }));
748:   rim2.rotation.x = Math.PI / 2; rim2.position.y = 0.02; group.add(rim2);
