773:   // Neon arch frames behind the car.
774:   for (const [x, color] of [[-7, 0x22e4ff], [7, 0xff2d9a]]) {
775:     const arch = new THREE.Group();
776:     const bar = new THREE.Mesh(new THREE.TorusGeometry(4.2, 0.035, 6, 32, Math.PI), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
777:     bar.rotation.z = 0; bar.position.y = 4; arch.add(bar);
778:     const line = new THREE.Mesh(new THREE.BoxGeometry(0.05, 4, 0.05), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
779:     line.position.set(-4.2, 2, 0); arch.add(line);
