788:     const lantern = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 6), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
789:     lantern.position.set(-6 + (i % 6) * 2.4, 2.8 + Math.floor(i / 6) * 1.1, -3.5);
790:     group.add(lantern);
791:     const string = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 1, 4), new THREE.MeshBasicMaterial({ color: 0x292633 }));
792:     string.position.copy(lantern.position); string.position.y += 0.58; group.add(string);
793:   }
