795:   // Wall sign.
796:   const c = canvas2d(1024, 256);
797:   const x = c.getContext('2d');
798:   x.fillStyle = '#08060f'; x.fillRect(0, 0, 1024, 256);
799:   x.strokeStyle = '#ff2d9a'; x.lineWidth = 5; x.strokeRect(6, 6, 1012, 244);
800:   x.fillStyle = '#ff2d9a'; x.font = '900 150px Bebas Neue, sans-serif'; x.textAlign = 'center';
801:   x.fillText('TOKYO REDLINE', 512, 145);
802:   x.fillStyle = '#8ef8eb'; x.font = '900 34px "Noto Sans JP", sans-serif';
803:   x.fillText('東京 ・ 夜間走行', 512, 210);
804:   const sign = new THREE.Mesh(new THREE.PlaneGeometry(12.8, 3.2), new THREE.MeshBasicMaterial({ map: texFrom(c), toneMapped: false }));
805:   sign.position.set(0, 8.8, -18.5);
806:   group.add(sign);
