809:   ['夜間', '速度', '夢'].forEach((t, i) => {
810:     const color = NEON_COLORS[i];
811:     const ms = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 5.2), new THREE.MeshBasicMaterial({ map: signTexture(t, color), side: THREE.DoubleSide, toneMapped: false }));
812:     ms.position.set(-13 + i * 13, 5.2, -15.5);
