844:       particles.rotation.y = t * 0.01;
845:       rim.rotation.z = t * 0.06;
846:       rim2.rotation.z = -t * 0.04;
847:       sign.material.opacity = 0.9 + Math.sin(t * 2.2) * 0.1;
848:     },
849:     setTheme(track) {
