856: export function createRaceEnvironment(scene, track, distance) {
857:   scene.background = new THREE.Color(track.colors.top);
858:   scene.fog = new THREE.FogExp2(track.colors.fog, track.kind === 'garage' ? 0.012 : track.kind === 'city' ? 0.0085 : 0.0042);
859:   const group = new THREE.Group();
860:   const cfg = track.colors;
861:   const random = rng((track.id.charCodeAt(0) + distance) | 0);
862: 
863:   addSky(scene, cfg, track.kind);
864:   if (['city', 'osaka', 'future', 'mountain', 'waterfront', 'harbour', 'garage'].includes(track.kind)) addStars(scene, cfg.accent);
865: 
866:   addRoad(scene, track, distance);
867:   const gantry = addStartGantry(scene, track, distance);
868: 
869:   const kinds = new Set(track.props || []);
870:   if (track.kind === 'city' || track.kind === 'future') addCity(scene, track, distance, { seed: 17, tall: track.kind === 'future' });
871:   if (track.kind === 'osaka') addCity(scene, track, distance, { seed: 30, low: true });
872:   if (track.kind === 'waterfront') {
873:     addCity(scene, track, distance, { seed: 48, low: true });
874:     addWater(scene, cfg, distance, 1);
875:     addContainers(scene, distance, cfg);
876:     const ferris = addFerrisWheel(scene, 76, -105, cfg.glow);
877:     group.userData.ferris = ferris;
878:   }
879:   if (track.kind === 'mountain') {
880:     addMountains(scene, cfg, distance, 1.2);
881:     addTrees(scene, distance, 0x184c3f, 0xff9ec6);
882:     addTorii(scene, 0, -70, 1.2, 0xdd3a4b);
883:   }
884:   if (track.kind === 'garage') addGarage(scene, cfg, distance);
885:   if (track.kind === 'harbour') {
886:     addContainers(scene, distance, cfg);
887:     addWater(scene, cfg, distance, -1);
888:     addMountains(scene, cfg, distance, 0.25);
889:   }
890:   if (track.kind === 'airport') addAirport(scene, cfg, distance);
891:   if (track.kind === 'coast') {
892:     addWater(scene, cfg, distance, 1);
893:     addPalms(scene, distance);
894:     addFerrisWheel(scene, 82, -220, cfg.warm);
895:     addCity(scene, track, distance, { seed: 73, low: true });
896:   }
897:   if (track.kind === 'countryside') addCountryside(scene, cfg, distance);
898:   if (track.kind === 'future') {
899:     addHologram(scene, distance, cfg);
900:     addCity(scene, track, distance, { seed: 211, tall: true });
901:   }
902: 
903:   // Ground mist/haze.
904:   const haze = new THREE.Mesh(new THREE.PlaneGeometry(350, distance + 500), new THREE.MeshBasicMaterial({ color: cfg.fog, transparent: true, opacity: 0.12, depthWrite: false }));
905:   haze.rotation.x = -Math.PI / 2; haze.position.set(0, 0.12, -distance / 2); scene.add(haze);
906: 
907:   // Start-line crowd.
908:   const crowdGroup = new THREE.Group();
909:   const crowdRand = rng(101);
910:   const crowdCount = Math.floor(120 * (track.crowd || 1));
911:   const bodyGeo = new THREE.CapsuleGeometry(0.16, 0.4, 3, 5);
912:   const headGeo = new THREE.SphereGeometry(0.14, 6, 5);
913:   const colors = [0xff4d84, 0x3bffd7, 0xffd84a, 0x8d5bff, 0xff7a42, 0xf4efe1];
914:   const crowdMats = colors.map(c => new THREE.MeshToonMaterial({ color: c }));
915:   for (let i = 0; i < crowdCount; i++) {
916:     const side = i % 2 ? 1 : -1;
917:     const x = side * (15 + crowdRand() * 7);
918:     const row = Math.floor(crowdRand() * 5);
919:     const z = 15 - crowdRand() * 55;
920:     const person = new THREE.Mesh(bodyGeo, crowdMats[Math.floor(crowdRand() * colors.length)]);
921:     person.position.set(x, 0.85 + row * 0.32, z);
922:     person.rotation.y = crowdRand() * 6;
923:     crowdGroup.add(person);
924:     const head = new THREE.Mesh(headGeo, new THREE.MeshToonMaterial({ color: crowdRand() > 0.5 ? 0xd8a476 : 0x7d573f }));
925:     head.position.set(x, 1.3 + row * 0.32, z); crowdGroup.add(head);
926:   }
927:   scene.add(crowdGroup);
928: 
929:   // Light arch reflections on the ground.
930:   for (let i = 0; i < 5; i++) {
931:     const z = -8 - i * (distance / 5);
932:     const strip = new THREE.Mesh(new THREE.PlaneGeometry(18, 0.7), new THREE.MeshBasicMaterial({ color: i % 2 ? cfg.glow : cfg.accent, transparent: true, opacity: 0.2, blending: THREE.AdditiveBlending, depthWrite: false }));
933:     strip.rotation.x = -Math.PI / 2; strip.position.set(0, 0.05, z); scene.add(strip);
934:   }
935: 
936:   let rain = null;
937:   if (track.rain) rain = addRain(scene);
938: 
939:   // Global light rig.
940:   const hemi = new THREE.HemisphereLight(cfg.top, 0x1b1119, 1.5); scene.add(hemi);
941:   const moon = new THREE.DirectionalLight(cfg.accent, 1.25); moon.position.set(-30, 40, -30); scene.add(moon);
942:   const rim = new THREE.DirectionalLight(cfg.glow, 1.1); rim.position.set(35, 25, 20); scene.add(rim);
943:   const startLight = new THREE.PointLight(cfg.glow, 12, 60, 2); startLight.position.set(0, 8, -3); scene.add(startLight);
944:   const finishLight = new THREE.PointLight(cfg.accent, 14, 70, 2); finishLight.position.set(0, 8, -distance); scene.add(finishLight);
945:   const ambient = new THREE.AmbientLight(0xffffff, 0.22); scene.add(ambient);
946: 
947:   const tempColor = new THREE.Color();
948:   function setStartLights(step) {
949:     // step: -1 all off, 0 amber1, 1 amber2, 2 amber3, 3 green.
950:     for (const set of [gantry.treeLights, gantry.laneLights]) {
951:       set.forEach((l, i) => {
952:         let on = false;
953:         if (step === 3) on = i === 3;
954:         else if (step >= 0) on = i <= step;
955:         if (on) {
956:           l.mat.color.setHex(l.color);
957:           l.mesh.scale.setScalar(1.2 + (step === 3 ? Math.sin(performance.now() * 0.02) * 0.08 : 0));
958:         } else {
959:           l.mat.color.setHex(0x201e26);
960:           l.mesh.scale.setScalar(1);
961:         }
962:       });
963:     }
964:     tempColor.setHex(step === 3 ? cfg.accent : step >= 0 ? cfg.warm : cfg.fog);
965:     startLight.color.copy(tempColor);
966:     startLight.intensity = step >= 0 ? 16 : 4;
967:   }
968:   setStartLights(-1);
969: 
970:   const clockStart = performance.now();
971:   return {
972:     group, setStartLights, gantry,
973:     update(dt, elapsed, speed = 0) {
974:       if (rain) {
975:         const p = rain.positions;
976:         for (let i = 0; i < rain.count; i++) {
977:           p[i * 6 + 1] -= dt * (32 + speed * 0.8);
978:           p[i * 6 + 4] -= dt * (32 + speed * 0.8);
979:           if (p[i * 6 + 1] < 0) {
980:             p[i * 6 + 1] += 40; p[i * 6 + 4] += 40;
981:             p[i * 6] = (Math.random() - 0.5) * 80; p[i * 6 + 3] = p[i * 6] + 0.04;
982:           }
983:         }
984:         rain.mesh.geometry.attributes.position.needsUpdate = true;
985:         rain.mesh.position.z = Math.max(-35, -speed * 0.4);
986:       }
987:       if (group.userData.ferris) group.userData.ferris.userData.wheel.rotation.z = elapsed * 0.06;
988:       // crowd bounce
989:       // (cheap: only a subtle group bob)
990:       crowdGroup.position.y = Math.sin(elapsed * 3.1) * 0.03;
991:     }
992:   };
993: }
994: 
995: export { addStars, signTexture, radialTexture, texFrom, makeWindowTexture };

