/* ---------- cinematic screen overlays ---------- */
.screen-fx { position: absolute; inset: 0; z-index: 2; pointer-events: none; overflow: hidden; }
.fx-grid {
  position: absolute; inset: -10%;
  background-image:
    linear-gradient(rgba(255,255,255,.03) 1px, transparent 1px),
