  font-family: var(--font-display); font-size: 20px; line-height: 1;
  background: linear-gradient(150deg, var(--pink), var(--violet));
  color: #fff; box-shadow: inset 0 0 0 1px rgba(255,255,255,.2);
}
.brand-mark span:last-child { background: linear-gradient(150deg, var(--cyan), #1a8dff); color: #071018; }
.brand-name { display: flex; flex-direction: column; line-height: .85; text-align: left; }
.brand-name b { font-family: var(--font-display); font-size: 22px; letter-spacing: .12em; color: var(--ink); }
.brand-name em { font-family: var(--font-display); font-style: normal; font-size: 22px; letter-spacing: .22em; color: var(--pink); }
.brand-jp { font-family: var(--font-jp); font-size: 10px; letter-spacing: .25em; color: var(--ink-dim); writing-mode: vertical-rl; margin-left: 4px; }

#main-tabs { display: flex; align-items: center; gap: 4px; margin-left: auto; }
#main-tabs button {
  position: relative;
  border: 0; background: transparent; cursor: pointer;
  padding: 10px 14px;
  font-weight: 700; font-size: 12px; letter-spacing: .18em;
  color: var(--ink-dim);
  transition: color .18s, background .18s;
}
#main-tabs button::after {
  content: ''; position: absolute; left: 14px; right: 14px; bottom: 3px; height: 2px;
  background: linear-gradient(90deg, var(--pink), var(--cyan));
  transform: scaleX(0); transform-origin: left; transition: transform .2s;
}
#main-tabs button:hover, #main-tabs button.is-active { color: var(--ink); }
#main-tabs button.is-active::after, #main-tabs button:hover::after { transform: scaleX(1); }

.top-actions { display: flex; align-items: center; gap: 8px; margin-left: 12px; }
.cash-chip, .career-chip {
  display: flex; align-items: baseline; gap: 5px;
  padding: 7px 12px;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.04);
  clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
}
.cash-symbol { color: var(--lime); font-weight: 800; }
.cash-chip span:last-child { font-weight: 800; font-size: 15px; letter-spacing: .04em; color: var(--lime); }
.career-chip { align-items: center; }
.career-chip .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--pink); box-shadow: 0 0 10px var(--pink); }
.career-chip span { font-weight: 800; font-size: 15px; }
.career-chip small { color: var(--ink-dim); font-size: 9px; letter-spacing: .16em; margin-left: 1px; }
.icon-btn {
  width: 36px; height: 36px; display: grid; place-items: center;
  border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.04);
  cursor: pointer; transition: border .2s, background .2s, transform .15s;
}
.icon-btn:hover { border-color: var(--cyan); background: rgba(37,244,255,.08); transform: translateY(-1px); }
.icon-btn svg { width: 19px; height: 19px; fill: none; stroke: var(--ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn.is-off svg { opacity: .35; }
.icon-btn.is-off::after { content: ''; position: absolute; width: 24px; height: 2px; background: var(--pink); transform: rotate(-45deg); }

#screen-root {
  position: relative;
  z-index: 6;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 20px 28px 18px;
}
.screen { display: none; min-height: 100%; flex-direction: column; gap: 18px; animation: screenIn .32s cubic-bezier(.2,.8,.2,1); }
.screen.is-active { display: flex; }
@keyframes screenIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }

.glass-panel {
  position: relative;
  background:
    linear-gradient(148deg, rgba(34, 24, 55, .86), rgba(13, 10, 22, .92) 58%),
    var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,.05);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
}
.glass-panel::before {
  content: ''; position: absolute; top: 0; left: 0; width: 45%; height: 2px;
  background: linear-gradient(90deg, var(--pink), transparent);
  pointer-events: none;
}

.eyebrow {
  display: flex; align-items: center; gap: 10px;
  font-size: 10px; font-weight: 700; letter-spacing: .26em; color: var(--cyan);
}
.eyebrow-line { width: 28px; height: 2px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.screen-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; }
.screen-head.compact { align-items: center; }
.screen-title {
  margin: 2px 0 0;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(42px, 5vw, 64px);
  line-height: .86;
  letter-spacing: .03em;
  text-shadow: 0 8px 30px rgba(0,0,0,.55);
}
.screen-title em { font-style: normal; color: var(--pink); text-shadow: 0 0 28px rgba(255,45,154,.35); }
.screen-note { margin: 0; color: var(--ink-dim); font-size: 13px; line-height: 1.55; text-align: right; }
.screen-note span { color: var(--cyan); font-weight: 800; }
.section-label { display: flex; align-items: center; gap: 10px; font-size: 11px; font-weight: 800; letter-spacing: .22em; color: var(--ink-dim); }
.section-label span { color: var(--pink); }
.panel-kicker {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  font-size: 9px; font-weight: 800; letter-spacing: .22em; color: var(--ink-dim);
}
.panel-kicker .live-dot { color: var(--lime); }
.small-copy { margin: 0; color: var(--ink-dim); font-size: 12.5px; line-height: 1.55; }
.tiny-copy { margin: 0; font-size: 10px; letter-spacing: .06em; color: rgba(255,255,255,.38); text-align: center; }
.is-disabled { opacity: .55; pointer-events: none; }

/* ---------- CTAs ---------- */
.cta {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  border: 0; cursor: pointer;
  padding: 14px 24px;
  font-family: var(--font-body);
  font-weight: 800; font-size: 12px; letter-spacing: .17em;
  text-transform: uppercase; color: #090711;
  background: linear-gradient(105deg, var(--cyan), #31ffd0);
  clip-path: polygon(0 0, 100% 0, calc(100% - 13px) 100%, 0 100%);
  transition: transform .16s, filter .16s, background .16s;
  white-space: nowrap;
}
.cta:hover { transform: translateY(-2px); filter: brightness(1.1); }
.cta:active { transform: translateY(0); }
.cta svg { width: 26px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; }
.cta.primary { background: linear-gradient(105deg, var(--pink), #ff6b45); color: #fff; box-shadow: 0 10px 34px rgba(255,45,154,.28); }
.cta.hot { background: linear-gradient(105deg, var(--gold), var(--pink)); color: #100812; }
.cta.ghost {
  background: rgba(255,255,255,.05);
  color: var(--ink);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.18);
}
.cta.ghost:hover { background: rgba(255,255,255,.1); }
.cta.sm { padding: 10px 16px; font-size: 10px; letter-spacing: .14em; }
.cta.wide { width: 100%; }
.cta.compact { padding: 10px 18px; }
.cta.compact b { color: var(--pink); }
.cta:disabled { opacity: .38; cursor: not-allowed; transform: none; filter: grayscale(.5); }
.cta.danger { color: #ff8794; }

/* ---------- tags, stats ---------- */
.tag {
  display: inline-flex; align-items: center;
  padding: 4px 8px;
  border: 1px solid rgba(255,255,255,.14);
  font-size: 9px; font-weight: 700; letter-spacing: .12em;
  color: var(--ink-dim);
  background: rgba(255,255,255,.04);
}
.build-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.stat-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: rgba(255,255,255,.08); }
.stat-strip > div { padding: 12px 10px; background: rgba(9,7,16,.88); display: flex; flex-direction: column; gap: 1px; }
.stat-strip small { font-size: 8px; letter-spacing: .18em; color: var(--ink-dim); }
.stat-strip b { font-family: var(--font-display); font-size: 26px; line-height: .95; color: var(--cyan); }
.stat-strip span { font-size: 8px; letter-spacing: .14em; color: rgba(255,255,255,.35); }
.big-stats { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.big-stats > div { padding: 12px 8px; display: flex; flex-direction: column; }
.big-stats small { font-size: 8px; letter-spacing: .18em; color: var(--ink-dim); }
.big-stats b { font-family: var(--font-display); font-size: 32px; line-height: 1; color: var(--ink); }
.big-stats span { font-size: 8px; letter-spacing: .16em; color: var(--pink); }
.stat-bars { display: flex; flex-direction: column; gap: 7px; }
.stat-bar { display: grid; grid-template-columns: 55px 1fr 54px; align-items: center; gap: 8px; }
.stat-bar span { font-size: 8px; font-weight: 700; letter-spacing: .14em; color: var(--ink-dim); }
.stat-bar i { height: 5px; background: rgba(255,255,255,.08); overflow: hidden; transform: skew(-18deg); }
.stat-bar i b { display: block; height: 100%; background: linear-gradient(90deg, var(--pink), var(--cyan)); box-shadow: 0 0 12px rgba(37,244,255,.35); }
.stat-bar em { font-style: normal; font-size: 9px; font-weight: 700; color: var(--ink); text-align: right; }

/* ---------- HOME ---------- */
.home-screen.is-active {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(340px, .72fr);
  grid-template-rows: 1fr auto;
  gap: 22px 34px;
  padding: 16px 12px 2px;
}
.home-copy { align-self: center; max-width: 700px; }
.hero-title {
  margin: 8px 0 10px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(72px, 10.5vw, 150px);
  line-height: .78;
  letter-spacing: .015em;
  text-shadow: 0 14px 50px rgba(0,0,0,.7);
}
.hero-title span { display: block; color: var(--ink); }
.hero-title em {
  display: block; font-style: normal; color: transparent;
  background: linear-gradient(100deg, var(--pink) 5%, #ff8a3d 48%, var(--gold));
  -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 0 32px rgba(255,45,154,.32));
}
.hero-sub { margin: 0 0 22px; font-size: 14px; line-height: 1.55; letter-spacing: .1em; color: var(--ink-dim); }
.hero-sub strong { color: var(--ink); font-weight: 700; }
.hero-metrics { display: flex; gap: 28px; margin-bottom: 26px; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.hero-metrics > div { display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 9px; }
.hero-metrics b { font-family: var(--font-display); font-size: 38px; line-height: 1; color: var(--cyan); }
.hero-metrics span { max-width: 70px; font-size: 8px; font-weight: 700; letter-spacing: .17em; line-height: 1.35; color: var(--ink-dim); }
.home-copy > .cta { font-size: 14px; padding: 18px 36px; }

.home-build-card { align-self: center; padding: 18px; }
.build-head { display: flex; align-items: center; gap: 13px; margin: 16px 0; }
.car-avatar {
  flex: 0 0 68px; height: 68px; display: grid; place-items: center;
  border: 1px solid rgba(255,255,255,.16);
  background:
    radial-gradient(circle at 35% 30%, rgba(37,244,255,.28), transparent 60%),
    linear-gradient(145deg, rgba(255,45,154,.22), rgba(12,10,20,.8));
  font-family: var(--font-display); font-size: 26px; letter-spacing: .04em; color: var(--cyan);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.build-head > div:last-child { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.build-head small { font-size: 9px; letter-spacing: .2em; color: var(--pink); }
.build-head h3 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: 27px; line-height: 1; letter-spacing: .03em; }
.build-head p { margin: 2px 0 0; font-size: 10px; letter-spacing: .12em; color: var(--ink-dim); }
.home-build-card .stat-strip { margin-bottom: 12px; }
.home-build-card .build-tags { margin-bottom: 16px; }
.build-actions { display: flex; gap: 8px; }
.build-actions .cta { flex: 1; }

.home-footer {
  grid-column: 1 / -1;
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.active-coords, .rival-mini { display: flex; align-items: center; gap: 10px; }
.active-coords small, .rival-mini small { display: block; font-size: 8px; letter-spacing: .2em; color: var(--ink-dim); }
.active-coords b, .rival-mini b { font-size: 12px; letter-spacing: .12em; }
.crosshair { color: var(--cyan); font-size: 18px; }
.home-tip { font-size: 9px; letter-spacing: .12em; color: var(--ink-dim); display: flex; align-items: center; gap: 7px; }
.key {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 19px; height: 19px; padding: 0 4px;
  border: 1px solid rgba(255,255,255,.22); border-bottom-width: 2px;
  font-size: 9px; font-weight: 800; color: var(--ink);
  background: rgba(255,255,255,.06);
}
.rival-mini { padding: 6px 8px; border-left: 2px solid var(--pink); }
.rival-avatar {
  flex: 0 0 34px; height: 34px; display: grid; place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--violet), var(--pink));
  font-family: var(--font-display); font-size: 19px; color: #fff;
  box-shadow: 0 0 16px rgba(255,45,154,.35);
}
.mini-arrow { border: 0; background: none; color: var(--cyan); font-size: 20px; cursor: pointer; padding: 2px 6px; }

/* ---------- GARAGE ---------- */
.garage-screen.is-active {
  display: grid;
  grid-template-columns: 310px minmax(0, 1fr) 360px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 16px;
}
.garage-screen .screen-head { grid-column: 1 / -1; }
.garage-list-panel { padding: 14px 12px; overflow: hidden; display: flex; flex-direction: column; }
.vehicle-list { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; overflow-y: auto; padding-right: 2px; }
.vehicle-item {
  display: flex; align-items: center; gap: 10px; text-align: left;
  border: 1px solid transparent; background: rgba(255,255,255,.025);
  padding: 8px; cursor: pointer; transition: background .16s, border .16s;
}
.vehicle-item:hover { background: rgba(255,255,255,.07); }
.vehicle-item.is-selected { border-color: rgba(37,244,255,.45); background: rgba(37,244,255,.06); }
.vehicle-item.is-active { box-shadow: inset 3px 0 0 var(--pink); }
.vehicle-swatch {
  flex: 0 0 46px; height: 34px; display: grid; place-items: center;
  background: linear-gradient(135deg, var(--swatch), rgba(8,6,15,.7));
  font-family: var(--font-display); font-size: 13px; color: rgba(255,255,255,.85);
  clip-path: polygon(0 0, 100% 0, calc(100% - 9px) 100%, 0 100%);
  text-shadow: 0 1px 4px rgba(0,0,0,.6);
}
.vehicle-meta { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.vehicle-meta small { font-size: 8px; letter-spacing: .16em; color: var(--ink-dim); }
.vehicle-meta b { font-size: 12px; letter-spacing: .03em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.vehicle-meta em { font-style: normal; font-size: 8px; letter-spacing: .1em; color: var(--pink); }
.vehicle-arrow { color: var(--cyan); font-size: 14px; }
.garage-info { padding: 16px; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; }
.garage-title-row { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
.garage-title-row small { font-size: 9px; letter-spacing: .2em; color: var(--pink); }
.garage-title-row h3 { margin: 1px 0 0; font-family: var(--font-display); font-weight: 400; font-size: 28px; line-height: .95; letter-spacing: .03em; }
.flag-jp { font-family: var(--font-jp); font-size: 16px; color: var(--cyan); white-space: nowrap; }
.garage-bottom { grid-column: 1 / -1; display: flex; justify-content: flex-end; gap: 10px; }
.garage-bottom .cta.primary { padding: 14px 30px; }

/* ---------- DEALER ---------- */
.dealer-screen.is-active { display: flex; }
.dealer-wallet { padding: 10px 18px; display: flex; flex-direction: column; }
.dealer-wallet small { font-size: 8px; letter-spacing: .2em; color: var(--ink-dim); }
.dealer-wallet b { font-family: var(--font-display); font-size: 30px; line-height: 1; color: var(--lime); }
.dealer-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 340px minmax(0, 1fr); gap: 16px; }
.dealer-detail { padding: 16px; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; }
.dealer-price-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; margin-top: auto; }
.dealer-price-row small { font-size: 8px; letter-spacing: .18em; color: var(--ink-dim); }
.dealer-price-row b { font-family: var(--font-display); font-size: 30px; line-height: 1; color: var(--gold); }
.dealer-price-row span { font-size: 8px; font-weight: 700; letter-spacing: .12em; color: var(--ink-dim); text-align: right; }
.dealer-browser { min-height: 0; display: flex; flex-direction: column; gap: 10px; }
.filter-row { display: flex; flex-wrap: wrap; gap: 5px; }
.filter-row button {
  border: 1px solid var(--line); background: rgba(255,255,255,.03); cursor: pointer;
  padding: 6px 10px; font-size: 9px; font-weight: 700; letter-spacing: .13em; color: var(--ink-dim);
  transition: .16s;
}
.filter-row button:hover { color: var(--ink); border-color: rgba(255,255,255,.3); }
.filter-row button.active { color: #08060f; background: var(--cyan); border-color: var(--cyan); }
.dealer-grid {
  flex: 1; min-height: 0; overflow-y: auto;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px;
  align-content: start; padding-right: 2px;
}
.dealer-card {
  position: relative; display: flex; flex-direction: column; text-align: left;
  border: 1px solid rgba(255,255,255,.08); background: rgba(12,9,21,.72);
  padding: 0; cursor: pointer; overflow: hidden;
  transition: border .16s, background .16s, transform .16s;
}
.dealer-card:hover { border-color: rgba(37,244,255,.4); background: rgba(20,15,34,.92); transform: translateY(-2px); }
.dealer-card.is-selected { border-color: var(--cyan); box-shadow: 0 0 0 1px rgba(37,244,255,.25), 0 8px 24px rgba(0,0,0,.4); }
.dealer-card.is-locked .dealer-art { filter: grayscale(.9) brightness(.55); }
.dealer-card.is-owned .dealer-badge { background: var(--lime); color: #071006; }
.dealer-art {
  position: relative; height: 66px; display: block;
  background:
    radial-gradient(ellipse at 50% 115%, var(--accent) 0%, transparent 56%),
    linear-gradient(160deg, rgba(255,255,255,.07), transparent 45%),
    linear-gradient(130deg, var(--swatch), rgba(8,6,15,.92) 78%);
  overflow: hidden;
}
.dealer-art::after {
  content: ''; position: absolute; left: 8%; right: 8%; bottom: 11px; height: 4px;
  background: rgba(0,0,0,.45); filter: blur(3px);
}
.dealer-art i {
  position: absolute; left: 15%; right: 15%; bottom: 14px; height: 19px;
  background: linear-gradient(180deg, rgba(255,255,255,.4), var(--swatch) 42%, rgba(0,0,0,.45));
  clip-path: polygon(8% 0, 88% 2%, 100% 48%, 92% 100%, 6% 100%, 0 48%);
}
.dealer-art b {
  position: absolute; right: 7px; bottom: 4px;
  font-family: var(--font-display); font-weight: 400; font-size: 14px; color: rgba(255,255,255,.8);
  letter-spacing: .04em;
}
.dealer-card-info { display: flex; flex-direction: column; gap: 1px; padding: 7px 8px 8px; }
.dealer-card-info small { font-size: 7px; letter-spacing: .18em; color: var(--pink); }
.dealer-card-info strong { font-size: 10.5px; font-weight: 700; letter-spacing: .02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dealer-badge {
  position: absolute; top: 5px; right: 5px;
  padding: 2px 5px; background: rgba(8,6,15,.78); color: var(--gold);
  font-size: 7px; font-weight: 800; letter-spacing: .1em;
}
.dealer-lock {
  position: absolute; left: 5px; top: 5px; padding: 2px 5px;
  background: var(--red); color: #fff; font-size: 7px; font-weight: 800; letter-spacing: .1em;
}

/* ---------- CUSTOMIZE ---------- */
.customize-screen.is-active { display: flex; }
.custom-budget { padding: 10px 18px; display: flex; flex-direction: column; }
.custom-budget small { font-size: 8px; letter-spacing: .2em; color: var(--ink-dim); }
.custom-budget b { font-family: var(--font-display); font-size: 30px; line-height: 1; color: var(--lime); }
.custom-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 290px minmax(0, 1fr) 370px; gap: 16px; }
.custom-stats { padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.build-summary { display: flex; flex-direction: column; gap: 5px; margin-top: auto; }
.build-summary span { font-size: 8px; letter-spacing: .2em; color: var(--ink-dim); }
.build-summary b { font-size: 10px; font-weight: 600; color: var(--ink); }
.custom-shop { padding: 14px; display: flex; flex-direction: column; gap: 10px; overflow: hidden; }
.custom-tabs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; }
.custom-tabs button {
  border: 1px solid var(--line); background: rgba(255,255,255,.03); cursor: pointer;
  padding: 7px 4px; font-size: 8px; font-weight: 800; letter-spacing: .12em; color: var(--ink-dim);
  transition: .16s;
}
.custom-tabs button:hover { color: var(--ink); }
.custom-tabs button.active { background: linear-gradient(110deg, var(--pink), #ff6b45); color: #fff; border-color: transparent; }
.custom-option-head { display: flex; align-items: baseline; justify-content: space-between; padding-bottom: 4px; border-bottom: 1px solid var(--line); }
.custom-option-head b { font-family: var(--font-display); font-weight: 400; font-size: 22px; letter-spacing: .06em; }
.custom-option-head span { font-size: 7px; letter-spacing: .14em; color: var(--ink-dim); }
.custom-options { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding-right: 2px; }
.part-group { display: flex; flex-direction: column; gap: 5px; }
.part-group-head { display: flex; align-items: center; gap: 8px; font-size: 8px; font-weight: 800; letter-spacing: .18em; color: var(--cyan); }
.part-group-head i { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(37,244,255,.3), transparent); }
.part-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.part-card {
  display: flex; align-items: center; gap: 7px; text-align: left;
  border: 1px solid var(--line); background: rgba(255,255,255,.025);
  padding: 7px; cursor: pointer; transition: .16s; min-height: 44px;
}
.part-card:hover { background: rgba(255,255,255,.07); border-color: rgba(255,255,255,.24); }
.part-card.is-selected { border-color: var(--cyan); background: rgba(37,244,255,.07); }
.part-card > span { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.part-card b { font-size: 10px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.part-card em { font-style: normal; font-size: 7px; letter-spacing: .08em; color: var(--ink-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.part-card small { font-size: 7px; font-weight: 800; letter-spacing: .08em; color: var(--gold); white-space: nowrap; }
.part-card.is-owned small { color: var(--lime); }
.part-swatch { flex: 0 0 13px; height: 26px; background: var(--swatch); border: 1px solid rgba(255,255,255,.25); }
.custom-footer { display: flex; justify-content: space-between; gap: 10px; }

/* ---------- EVENTS ---------- */
.event-grid { flex: 1; min-height: 0; overflow-y: auto; display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; align-content: start; padding: 2px; }
.event-card {
  position: relative; padding: 14px; display: flex; flex-direction: column; gap: 9px;
  background: linear-gradient(160deg, color-mix(in srgb, var(--event) 22%, #0b0814), rgba(10,8,18,.94) 64%);
  border: 1px solid color-mix(in srgb, var(--event) 42%, transparent);
  box-shadow: 0 16px 44px rgba(0,0,0,.42);
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 0 100%);
  overflow: hidden;
}
.event-card::before { content: ''; position: absolute; top: 0; left: 0; width: 50%; height: 2px; background: var(--event); box-shadow: 0 0 18px var(--event); }
.event-card.is-locked { opacity: .58; }
.event-card.is-complete { filter: saturate(.6); }
.event-top { display: flex; justify-content: space-between; align-items: center; }
.event-badge { padding: 3px 7px; background: var(--event); color: #08060f; font-size: 8px; font-weight: 900; letter-spacing: .16em; }
.event-jp { font-family: var(--font-jp); font-size: 12px; color: var(--event); }
.event-card h3 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: 27px; line-height: .92; letter-spacing: .03em; }
.event-card p { margin: 0; font-size: 10.5px; line-height: 1.45; color: var(--ink-dim); min-height: 30px; }
.event-meta { display: grid; grid-template-columns: 1.35fr .8fr .55fr; gap: 1px; background: rgba(255,255,255,.07); }
.event-meta > div { background: rgba(8,6,15,.7); padding: 6px 7px; display: flex; flex-direction: column; }
.event-meta small, .event-foot small { font-size: 6.5px; letter-spacing: .16em; color: var(--ink-dim); }
.event-meta b { font-size: 9px; letter-spacing: .04em; color: var(--ink); }
.event-progress { height: 3px; background: rgba(255,255,255,.1); }
.event-progress i { display: block; height: 100%; background: var(--event); box-shadow: 0 0 10px var(--event); }
.event-foot { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; margin-top: auto; }
.event-foot > div { display: flex; flex-direction: column; }
.event-foot b { font-family: var(--font-display); font-size: 22px; line-height: 1; color: var(--gold); }
.event-foot em { font-style: normal; font-size: 8px; color: var(--cyan); letter-spacing: .08em; }
.event-footer { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 11px 15px; }
.event-footer small { font-size: 7px; letter-spacing: .18em; color: var(--ink-dim); }
.event-footer b { display: block; font-size: 11px; letter-spacing: .1em; color: var(--cyan); }

/* ---------- RIVALS ---------- */
.rival-list { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; padding-right: 2px; }
.rival-row {
  display: grid; grid-template-columns: 42px 45px minmax(0, 1fr) auto 130px;
  align-items: center; gap: 12px;
  padding: 10px 14px;
  border: 1px solid rgba(255,255,255,.08);
  background: linear-gradient(90deg, rgba(255,255,255,.035), rgba(8,6,15,.6));
  transition: .16s;
}
.rival-row:hover { border-color: rgba(37,244,255,.35); background: rgba(20,15,34,.9); }
.rival-row.is-beaten { box-shadow: inset 3px 0 0 var(--lime); }
.rival-row.is-locked { opacity: .55; }
.rival-rank { font-family: var(--font-display); font-size: 26px; color: rgba(255,255,255,.26); }
.rival-info small { font-size: 7.5px; letter-spacing: .2em; color: var(--pink); }
.rival-info h3 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: 22px; line-height: 1; }
.rival-info h3 span { font-family: var(--font-body); font-size: 9px; font-weight: 700; letter-spacing: .1em; color: var(--cyan); margin-left: 6px; }
.rival-info p { margin: 1px 0 0; font-size: 10px; color: var(--ink-dim); font-style: italic; }
.rival-specs { display: flex; gap: 18px; }
.rival-specs > div { display: flex; flex-direction: column; }
.rival-specs small { font-size: 6.5px; letter-spacing: .15em; color: var(--ink-dim); }
.rival-specs b { font-family: var(--font-display); font-size: 19px; line-height: 1; color: var(--gold); }

/* ---------- RACE SETUP ---------- */
.setup-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 16px; }
.track-panel { min-height: 0; display: flex; flex-direction: column; gap: 10px; }
.track-grid { flex: 1; min-height: 0; overflow-y: auto; display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; align-content: start; padding: 1px; }
.track-card {
  position: relative; min-height: 118px; padding: 9px; text-align: left; cursor: pointer;
  border: 1px solid rgba(255,255,255,.09); overflow: hidden;
  background: linear-gradient(152deg, var(--t1), #0a0812 62%);
  transition: transform .16s, border .16s, box-shadow .16s;
}
.track-card:hover { transform: translateY(-2px); border-color: color-mix(in srgb, var(--t2) 55%, transparent); }
.track-card.is-selected { border-color: var(--t2); box-shadow: 0 0 0 1px var(--t2), 0 12px 30px rgba(0,0,0,.5); }
.track-card.is-locked { filter: grayscale(.6) brightness(.62); }
.track-jp { position: absolute; top: 6px; right: 7px; font-family: var(--font-jp); font-size: 11px; color: var(--t2); writing-mode: vertical-rl; letter-spacing: .16em; }
.track-index { font-size: 8px; font-weight: 700; letter-spacing: .15em; color: rgba(255,255,255,.42); }
.track-art { position: absolute; left: 9px; right: 9px; top: 22px; height: 43px; overflow: hidden; }
.track-art i { position: absolute; inset: auto 0 0; height: 22px; background: linear-gradient(180deg, transparent, rgba(0,0,0,.7)); }
.track-art b { position: absolute; left: 10%; right: 10%; bottom: 5px; height: 10px; background: linear-gradient(90deg, transparent, var(--t2), transparent); filter: blur(2px); }
.track-copy { position: absolute; left: 9px; right: 9px; bottom: 8px; display: flex; flex-direction: column; }
.track-copy b { font-family: var(--font-display); font-weight: 400; font-size: 19px; line-height: 1; letter-spacing: .04em; }
.track-copy small { font-size: 7px; letter-spacing: .1em; color: rgba(255,255,255,.5); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.track-lock { position: absolute; top: 7px; left: 8px; padding: 2px 5px; background: rgba(8,6,15,.8); color: var(--gold); font-size: 7px; font-weight: 800; letter-spacing: .08em; }
.setup-side { padding: 15px; display: flex; flex-direction: column; gap: 10px; overflow-y: auto; }
.setup-track-art {
  position: relative; height: 92px; display: flex; align-items: flex-end; justify-content: space-between;
  padding: 8px; background: linear-gradient(152deg, #210b4a, #33134c 50%, #ff6a8e); overflow: hidden;
}
.setup-track-art::before {
  content: ''; position: absolute; inset: 0;
  background:
    repeating-linear-gradient(90deg, transparent 0 14px, rgba(255,255,255,.06) 14px 15px),
    linear-gradient(180deg, transparent 50%, rgba(0,0,0,.5));
}
.setup-track-art .jp { position: relative; z-index: 1; font-family: var(--font-jp); font-size: 26px; color: #fff; text-shadow: 0 2px 14px rgba(0,0,0,.6); }
.setup-track-art .index { position: relative; z-index: 1; font-family: var(--font-display); font-size: 24px; color: rgba(255,255,255,.65); }
#setup-track-name { font-size: 9px; font-weight: 700; letter-spacing: .18em; color: var(--cyan); }
.setup-divider { height: 1px; background: linear-gradient(90deg, rgba(255,255,255,.15), transparent); }
.rival-select-head { display: flex; align-items: center; justify-content: space-between; }
.rival-select-head small { font-size: 7px; letter-spacing: .18em; color: var(--ink-dim); }
.rival-select-head span { font-size: 8px; font-weight: 800; letter-spacing: .12em; color: var(--pink); }
.setup-rival {
  display: flex; align-items: center; gap: 9px; padding: 8px; cursor: pointer;
  border: 1px solid rgba(255,255,255,.1); background: rgba(255,255,255,.03);
  transition: .16s;
}
.setup-rival:hover { border-color: rgba(37,244,255,.4); }
.setup-rival > div:nth-child(2) { display: flex; flex-direction: column; flex: 1; }
.setup-rival b { font-family: var(--font-display); font-weight: 400; font-size: 20px; line-height: 1; }
.setup-rival span { font-size: 8px; letter-spacing: .12em; color: var(--ink-dim); }
.rival-car { font-family: var(--font-display); font-size: 18px; color: var(--cyan); }
.setup-reward { display: flex; align-items: baseline; justify-content: space-between; padding: 7px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.setup-reward span { font-size: 7px; letter-spacing: .18em; color: var(--ink-dim); }
.setup-reward b { font-family: var(--font-display); font-size: 24px; color: var(--gold); line-height: 1; }
.race-length-card { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: rgba(255,255,255,.08); }
.race-length-card > div { background: rgba(8,6,15,.7); padding: 7px 8px; display: flex; flex-direction: column; }
.race-length-card small { font-size: 6.5px; letter-spacing: .16em; color: var(--ink-dim); }
.race-length-card b { font-size: 11px; letter-spacing: .06em; color: var(--ink); }
.distance-toggle, .records-tabs { display: flex; border: 1px solid var(--line); }
.distance-toggle button, .records-tabs button {
  border: 0; background: transparent; cursor: pointer; padding: 7px 14px;
  display: flex; flex-direction: column; align-items: center; gap: 0;
  color: var(--ink-dim); transition: .16s;
}
.distance-toggle button b { font-family: var(--font-display); font-size: 21px; line-height: 1; }
.distance-toggle button span { font-size: 6.5px; letter-spacing: .14em; }
.records-tabs button { font-size: 9px; font-weight: 800; letter-spacing: .13em; }
.distance-toggle button.active, .records-tabs button.active { background: linear-gradient(110deg, var(--pink), #ff6b45); color: #fff; }

/* ---------- RANKS ---------- */
.ranks-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 320px minmax(0, 1fr) 280px; gap: 16px; }
.record-hero { padding: 18px; cursor: pointer; display: flex; flex-direction: column; gap: 12px; background: linear-gradient(155deg, rgba(255,45,154,.16), rgba(13,10,22,.94) 56%); }
.record-time { font-family: var(--font-display); font-size: clamp(52px, 6vw, 76px); line-height: .82; letter-spacing: .02em; color: var(--cyan); text-shadow: 0 0 32px rgba(37,244,255,.25); }
.record-meta { font-size: 8px; letter-spacing: .15em; line-height: 1.6; color: var(--ink-dim); }
.record-car { margin-top: auto; font-family: var(--font-display); font-size: 32px; color: var(--pink); line-height: 1; }
.leaderboard { padding: 15px; display: flex; flex-direction: column; gap: 8px; min-height: 0; }
.leaderboard-rows { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.leaderboard-row {
  display: grid; grid-template-columns: 34px 1fr 70px 100px; gap: 8px; align-items: center;
  padding: 7px 8px; font-size: 10px;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.leaderboard-row.is-player { background: linear-gradient(90deg, rgba(37,244,255,.15), transparent); box-shadow: inset 2px 0 0 var(--cyan); }
.lb-rank { font-family: var(--font-display); font-size: 18px; color: rgba(255,255,255,.35); }
.lb-name { font-weight: 700; letter-spacing: .06em; }
.lb-car { font-size: 8px; letter-spacing: .08em; color: var(--ink-dim); }
.leaderboard-row b { font-family: var(--font-display); font-weight: 400; font-size: 17px; color: var(--cyan); text-align: right; }
.rank-notes { padding: 15px; display: flex; flex-direction: column; gap: 4px; }
.career-stat { display: flex; justify-content: space-between; align-items: baseline; padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,.06); }
.career-stat span { font-size: 7.5px; letter-spacing: .16em; color: var(--ink-dim); }
.career-stat b { font-family: var(--font-display); font-weight: 400; font-size: 23px; line-height: 1; color: var(--ink); }

/* ---------- toast ---------- */
.toast {
  position: fixed; left: 50%; bottom: 28px; z-index: 120;
  transform: translate(-50%, 20px); opacity: 0; pointer-events: none;
  padding: 11px 22px;
  background: linear-gradient(105deg, rgba(37,244,255,.95), rgba(185,255,47,.95));
  color: #08060f; font-size: 11px; font-weight: 900; letter-spacing: .13em;
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  transition: opacity .2s, transform .2s;
  box-shadow: 0 12px 40px rgba(37,244,255,.24);
  text-align: center; max-width: 88vw;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ================================================================
   RACE LAYER
   ================================================================ */
#race-layer { position: fixed; inset: 0; z-index: 50; }
#race-hud { position: absolute; inset: 0; pointer-events: none; }
#race-hud > * { pointer-events: none; }
#race-hud button { pointer-events: auto; }

.race-fx { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.race-lines {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 44%, rgba(8,6,15,.45) 100%);
}
.race-speedveil {
  position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(circle at 50% 50%, transparent 30%, rgba(37,244,255,.14) 82%, rgba(255,45,154,.2));
  mix-blend-mode: screen; transition: opacity .3s;
}
#race-layer[data-phase="running"] .race-speedveil { opacity: .7; animation: veilPulse 2.4s ease-in-out infinite; }
@keyframes veilPulse { 50% { opacity: .35; } }

.race-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; align-items: flex-start; gap: 14px;
  padding: 12px 18px 26px;
  background: linear-gradient(180deg, rgba(5,4,10,.86), rgba(5,4,10,.34) 62%, transparent);
}
#pause-btn {
  flex: 0 0 auto; width: 38px; height: 38px; margin-top: 3px;
  border: 1px solid rgba(255,255,255,.18); background: rgba(8,6,15,.55);
  color: var(--ink); font-size: 15px; cursor: pointer; letter-spacing: 0;
}
.race-location { display: flex; flex-direction: column; gap: 1px; min-width: 130px; }
.race-location small { font-family: var(--font-jp); font-size: 11px; color: var(--pink); letter-spacing: .16em; }
.race-location b { font-size: 14px; letter-spacing: .1em; }
.race-location span { font-size: 8px; letter-spacing: .16em; color: var(--ink-dim); }
.race-clock-wrap { flex: 0 1 300px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; gap: 3px; }
.race-clock-wrap small { font-size: 7px; letter-spacing: .2em; color: var(--ink-dim); }
#race-clock { font-family: var(--font-display); font-weight: 400; font-size: 29px; line-height: 1; letter-spacing: .04em; color: var(--ink); }
.race-progress { position: relative; width: 100%; height: 4px; background: rgba(255,255,255,.14); margin-top: 2px; overflow: visible; }
#progress-fill { height: 100%; width: 0; background: linear-gradient(90deg, var(--pink), var(--gold)); box-shadow: 0 0 12px rgba(255,45,154,.65); }
#rival-progress { position: absolute; top: -4px; left: 0; width: 3px; height: 12px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); transform: translateX(-1px); }
.race-progress-labels { display: flex; justify-content: space-between; width: 100%; font-size: 6.5px; letter-spacing: .14em; color: rgba(255,255,255,.4); }
.race-rival-chip { display: flex; flex-direction: column; gap: 0; min-width: 100px; text-align: right; }
.race-rival-chip small { font-size: 7px; letter-spacing: .18em; color: var(--ink-dim); }
.race-rival-chip b { font-family: var(--font-display); font-weight: 400; font-size: 22px; line-height: 1; color: var(--pink); }
.race-rival-chip span { font-size: 9px; font-weight: 700; letter-spacing: .08em; color: var(--cyan); }
.speed-cluster { display: flex; align-items: flex-end; gap: 9px; }
.speed-digits { display: flex; align-items: baseline; gap: 5px; }
.speed-digits b { font-family: var(--font-display); font-weight: 400; font-size: 58px; line-height: .8; letter-spacing: .02em; color: var(--ink); text-shadow: 0 0 30px rgba(37,244,255,.25); }
.speed-digits small { font-size: 8px; letter-spacing: .12em; color: var(--ink-dim); }
.gear-box { display: flex; flex-direction: column; align-items: center; padding: 3px 9px; border: 1px solid rgba(255,255,255,.2); background: rgba(8,6,15,.4); }
.gear-box small { font-size: 6px; letter-spacing: .18em; color: var(--ink-dim); }
.gear-box b { font-family: var(--font-display); font-weight: 400; font-size: 29px; line-height: .9; color: var(--gold); }

.start-tree {
  position: absolute; top: 88px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 8px 14px 7px;
  background: rgba(8,6,15,.64); border: 1px solid rgba(255,255,255,.1);
  backdrop-filter: blur(6px);
  clip-path: polygon(0 0, 100% 0, calc(100% - 9px) 100%, 9px 100%);
}
.tree-label { font-size: 7px; font-weight: 800; letter-spacing: .26em; color: var(--ink-dim); }
.tree-bulbs { display: flex; gap: 9px; }
.bulb { width: 16px; height: 16px; border-radius: 50%; background: #221e2a; border: 1px solid rgba(255,255,255,.14); transition: .08s; }
.bulb.amber.on { background: var(--gold); box-shadow: 0 0 16px var(--gold), 0 0 4px #fff inset; }
.bulb.green.on { background: var(--lime); box-shadow: 0 0 20px var(--lime), 0 0 4px #fff inset; }
.tree-reaction { font-size: 7px; font-weight: 700; letter-spacing: .16em; color: var(--cyan); white-space: nowrap; }

.shift-light-row { position: absolute; top: 158px; left: 50%; transform: translateX(-50%); display: flex; gap: 3px; }
.shift-light-row span { width: 22px; height: 4px; background: rgba(255,255,255,.12); transform: skew(-22deg); transition: .06s; }
.shift-light-row span.on { background: var(--lime); box-shadow: 0 0 10px var(--lime); }
.shift-light-row span.red { background: var(--red); box-shadow: 0 0 13px var(--red); }

.race-message {
  position: absolute; top: 34%; left: 50%; transform: translate(-50%, 8px) scale(.94);
  font-family: var(--font-display); font-weight: 400; font-size: clamp(28px, 5vw, 52px); letter-spacing: .06em;
  color: var(--ink); text-align: center; text-shadow: 0 4px 26px rgba(0,0,0,.7);
  opacity: 0; pointer-events: none; transition: .18s; white-space: nowrap;
}
.race-message.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.race-message.bad { color: var(--red); }
.race-message.perfect { color: var(--lime); text-shadow: 0 0 28px rgba(185,255,47,.55); }
.race-message.go { color: var(--lime); font-size: clamp(50px, 9vw, 100px); }
.race-message.warn { color: var(--gold); }

.race-status-pill {
  position: absolute; top: 210px; left: 18px;
  display: flex; align-items: center; gap: 6px; padding: 5px 9px;
  background: rgba(8,6,15,.55); border: 1px solid rgba(255,255,255,.12);
  font-size: 7px; font-weight: 800; letter-spacing: .16em; color: var(--ink-dim);
}
.race-status-pill .status-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.race-status-pill.running .status-dot { background: var(--lime); box-shadow: 0 0 8px var(--lime); }
.race-status-pill.penalty { color: var(--red); border-color: rgba(255,59,82,.5); }
.race-status-pill.penalty .status-dot { background: var(--red); box-shadow: 0 0 8px var(--red); }

.tach-strip { position: absolute; bottom: 214px; left: 50%; transform: translateX(-50%); width: min(46vw, 520px); height: 7px; background: rgba(8,6,15,.68); border: 1px solid rgba(255,255,255,.12); overflow: hidden; }
#tach-fill { height: 100%; width: 0; background: linear-gradient(90deg, var(--cyan), var(--gold) 66%, var(--red)); box-shadow: 0 0 12px rgba(255,213,46,.55); }
#rpm-readout { position: absolute; right: 0; top: -14px; font-size: 7px; letter-spacing: .12em; color: var(--ink-dim); }

.race-controls {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
  padding: 12px 18px 16px;
  background: linear-gradient(0deg, rgba(5,4,10,.9), rgba(5,4,10,.42) 66%, transparent);
}

/* H-pattern */
.shift-module { pointer-events: auto; width: 236px; padding: 8px 10px 9px; background: rgba(8,6,15,.62); border: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(7px); }
.shift-module-head { display: flex; justify-content: space-between; font-size: 6.5px; font-weight: 800; letter-spacing: .16em; color: var(--ink-dim); }
#shift-state { color: var(--gold); }
.hshift { position: relative; width: 100%; aspect-ratio: 200 / 150; margin-top: 2px; }
.shift-paths { position: absolute; inset: 0; width: 100%; height: 100%; }
.shift-paths path { fill: none; stroke: rgba(255,255,255,.22); stroke-width: 4; stroke-linecap: round; }
.gear-label {
  position: absolute; width: 22px; height: 18px; transform: translate(-50%, -50%);
  border: 1px solid rgba(255,255,255,.2); background: rgba(255,255,255,.05);
  font-family: var(--font-display); font-size: 13px; line-height: 1; color: var(--ink-dim);
  cursor: pointer; padding: 0; transition: .12s;
}
.gear-label:hover { color: var(--ink); border-color: var(--cyan); }
.gear-label.is-active { color: #08060f; background: var(--gold); border-color: var(--gold); box-shadow: 0 0 12px rgba(255,213,46,.5); }
.gear-label.g1 { left: 16%; top: 20%; }
.gear-label.g2 { left: 16%; top: 80%; }
.gear-label.g3 { left: 46%; top: 20%; }
.gear-label.g4 { left: 46%; top: 80%; }
.gear-label.g5 { left: 76%; top: 20%; }
.gear-label.g6 { left: 76%; top: 80%; }
.gear-label.gr { left: 92%; top: 80%; }
.gear-label.gn { left: 61%; top: 50%; width: 18px; height: 16px; font-size: 11px; }
.shift-knob {
  position: absolute; left: 61%; top: 50%; width: 26px; height: 18px; transform: translate(-50%, -50%);
  border-radius: 50% 50% 42% 42%; background: linear-gradient(160deg, #f6f1df, #7c8090 70%, #2f3038);
  box-shadow: 0 3px 9px rgba(0,0,0,.65), 0 0 13px rgba(255,255,255,.18);
  transition: left .07s linear, top .07s linear; pointer-events: none;
}
.shift-knob span { position: absolute; left: 50%; top: 42%; width: 7px; height: 7px; transform: translate(-50%, -50%); border-radius: 50%; background: #2a2931; }
.clutch-bar { display: flex; align-items: center; gap: 6px; font-size: 6px; letter-spacing: .14em; color: var(--ink-dim); }
.clutch-bar i { flex: 1; height: 3px; background: rgba(255,255,255,.12); overflow: hidden; }
#clutch-meter { display: block; height: 100%; width: 0; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); transition: width .05s; }

.steer-buttons { pointer-events: auto; display: flex; gap: 9px; padding-bottom: 4px; }
.steer-btn {
  width: 62px; height: 62px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.2); background: rgba(8,6,15,.55);
  color: var(--ink); font-size: 32px; line-height: 1; cursor: pointer;
  backdrop-filter: blur(6px); transition: .12s;
}
.steer-btn:hover { border-color: var(--cyan); background: rgba(37,244,255,.12); }
.steer-btn.is-pressed { background: var(--cyan); color: #08060f; }

.pedal-module { pointer-events: auto; width: 300px; display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.pedals { display: flex; gap: 7px; align-items: flex-end; width: 100%; }
.pedal {
  position: relative; flex: 1; height: 90px; cursor: pointer;
  border: 1px solid rgba(255,255,255,.16); background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(8,6,15,.72));
  display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 2px;
  padding: 5px 2px 8px; touch-action: none;
  clip-path: polygon(8% 0, 100% 0, 92% 100%, 0 100%);
  transition: background .1s, transform .08s;
}
.pedal span { font-size: 7.5px; font-weight: 800; letter-spacing: .1em; color: var(--ink-dim); }
.pedal b { font-size: 16px; font-family: var(--font-display); font-weight: 400; color: var(--ink); }
.pedal .pedal-travel { position: absolute; left: 0; right: 0; bottom: 0; height: 0; transition: height .08s; opacity: .5; }
.pedal.clutch .pedal-travel { background: var(--cyan); }
.pedal.brake .pedal-travel { background: var(--red); }
.pedal.gas .pedal-travel { background: var(--lime); }
.pedal.gas { height: 100px; }
.pedal.is-pressed { transform: translateY(2px); }
.pedal.is-pressed .pedal-travel { height: 72%; }
.pedal.is-pressed b { color: #fff; }
.nitro-button {
  display: flex; align-items: center; gap: 7px; padding: 5px 10px;
  border: 1px solid rgba(37,244,255,.45); background: rgba(8,6,15,.62);
  cursor: pointer; touch-action: none;
}
.nitro-bolt { font-size: 17px; color: var(--cyan); text-shadow: 0 0 10px var(--cyan); }
.nitro-label { font-size: 8px; font-weight: 900; letter-spacing: .16em; color: var(--ink); }
.nitro-button small { font-size: 7px; color: var(--ink-dim); border: 1px solid rgba(255,255,255,.2); padding: 0 3px; }
.nitro-fill { width: 52px; height: 4px; background: rgba(255,255,255,.12); overflow: hidden; }
.nitro-fill i { display: block; height: 100%; width: 0; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.nitro-button.is-firing { background: rgba(37,244,255,.3); box-shadow: 0 0 22px rgba(37,244,255,.5); }
.tire-heat { display: flex; align-items: center; gap: 6px; font-size: 6px; letter-spacing: .14em; color: var(--ink-dim); }
.tire-heat i { width: 90px; height: 3px; background: rgba(255,255,255,.12); overflow: hidden; }
.tire-heat b { display: block; height: 100%; width: 12%; background: linear-gradient(90deg, var(--gold), var(--red)); }

.race-toast { display: none; }
.race-tip-line {
  position: absolute; left: 50%; bottom: 136px; transform: translateX(-50%);
  font-size: 7.5px; letter-spacing: .14em; color: rgba(255,255,255,.55); white-space: nowrap;
  text-align: center;
}
.race-tip-line .key { min-width: 15px; height: 15px; font-size: 7px; }

/* pause */
.pause-overlay {
  position: fixed; inset: 0; z-index: 80;
  display: grid; place-items: center;
  background: rgba(4,3,9,.7); backdrop-filter: blur(9px);
}
.pause-card { width: min(92vw, 360px); padding: 24px; display: flex; flex-direction: column; gap: 10px; text-align: center; }
.pause-card h2 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: 50px; line-height: .9; }
.pause-card h2 em { font-style: normal; color: var(--pink); }
.pause-card p { margin: 0 0 6px; font-size: 11px; letter-spacing: .1em; color: var(--ink-dim); }

/* ================================================================
   MODALS
   ================================================================ */
.modal-root { position: fixed; inset: 0; z-index: 200; pointer-events: none; }
.modal-root > * { pointer-events: auto; }
.modal-scrim { position: absolute; inset: 0; background: rgba(4,3,9,.7); backdrop-filter: blur(8px); animation: fadeIn .2s; }
@keyframes fadeIn { from { opacity: 0; } }
.result-card {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(94vw, 530px); max-height: 94vh; overflow-y: auto;
  padding: 22px;
  display: flex; flex-direction: column; gap: 9px;
  animation: cardIn .28s cubic-bezier(.2,.85,.2,1);
}
@keyframes cardIn { from { opacity: 0; transform: translate(-50%, -46%) scale(.96); } }
.result-card.is-win { background: linear-gradient(150deg, rgba(255,45,154,.22), rgba(13,10,22,.96) 56%); }
.result-card.is-loss { background: linear-gradient(150deg, rgba(40,38,50,.7), rgba(11,9,18,.97) 56%); }
.result-card h2 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: 62px; line-height: .82; letter-spacing: .02em; }
.result-card h2 em { font-style: normal; color: var(--pink); }
.result-card p { margin: 0; font-size: 11px; letter-spacing: .12em; color: var(--ink-dim); }
.result-flag { position: absolute; right: 16px; top: 14px; font-family: var(--font-jp); font-size: 18px; color: rgba(255,255,255,.22); writing-mode: vertical-rl; letter-spacing: .18em; }
.result-times { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin: 4px 0; }
.result-times > div { padding: 8px 6px; display: flex; flex-direction: column; border-right: 1px solid rgba(255,255,255,.06); }
.result-times > div:nth-child(3n) { border-right: 0; }
.result-times small { font-size: 6.5px; letter-spacing: .15em; color: var(--ink-dim); }
.result-times b { font-family: var(--font-display); font-weight: 400; font-size: 21px; line-height: 1.05; color: var(--ink); }
.result-times b em { font-style: normal; font-size: 8px; color: var(--ink-dim); }
.result-times > div:first-child b { color: var(--cyan); }
.result-rewards { display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: baseline; padding: 4px 0; }
.result-rewards span { font-size: 7px; letter-spacing: .17em; color: var(--ink-dim); }
.result-rewards b { font-size: 12px; letter-spacing: .06em; color: var(--lime); }
.result-actions { display: flex; flex-direction: column; gap: 7px; margin-top: 5px; }
.result-note { color: rgba(255,255,255,.35); font-size: 7px; letter-spacing: .14em; text-align: center; }

.settings-card {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(94vw, 440px); padding: 22px; display: flex; flex-direction: column; gap: 12px;
  animation: cardIn .25s cubic-bezier(.2,.85,.2,1);
}
.settings-card h2 { margin: -2px 0 4px; font-family: var(--font-display); font-weight: 400; font-size: 42px; line-height: .9; }
.settings-card h2 em { font-style: normal; color: var(--cyan); }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 9px 0; border-bottom: 1px solid rgba(255,255,255,.07); }
.setting-row > div { display: flex; flex-direction: column; }
.setting-row b { font-size: 11px; letter-spacing: .1em; }
.setting-row small { font-size: 8px; letter-spacing: .05em; color: var(--ink-dim); }
.toggle { position: relative; width: 58px; height: 26px; border: 1px solid rgba(255,255,255,.2); background: rgba(255,255,255,.05); cursor: pointer; overflow: hidden; }
.toggle i { position: absolute; left: 3px; top: 3px; width: 18px; height: 18px; background: var(--ink-dim); transition: .18s; }
.toggle span { position: absolute; right: 6px; top: 7px; font-size: 7px; font-weight: 900; letter-spacing: .1em; color: var(--ink-dim); }
.toggle.on { border-color: var(--cyan); background: rgba(37,244,255,.12); }
.toggle.on i { left: 35px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.toggle.on span { right: auto; left: 7px; color: var(--cyan); }
.setting-note { font-size: 8.5px; line-height: 1.6; letter-spacing: .05em; color: var(--ink-dim); }
.settings-actions { display: flex; flex-direction: column; gap: 7px; }

/* ================================================================
   BOOT SCREEN
   ================================================================ */
#boot {
  position: fixed; inset: 0; z-index: 300;
  display: grid; place-items: center;
  background:
    radial-gradient(circle at 50% 46%, rgba(140,91,255,.2), transparent 42%),
    radial-gradient(circle at 70% 70%, rgba(255,45,154,.12), transparent 34%),
    #08060f;
  transition: opacity .55s, visibility .55s;
}
#boot.is-hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.boot-noise {
  position: absolute; inset: 0; opacity: .12; pointer-events: none;
  background: repeating-linear-gradient(180deg, rgba(255,255,255,.06) 0 1px, transparent 1px 4px);
  mix-blend-mode: soft-light;
}
.boot-logo { position: relative; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 20px; text-align: center; }
.boot-mark { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; transform: skew(-10deg); margin-bottom: 10px; }
.boot-mark span { width: 46px; height: 46px; display: grid; place-items: center; font-family: var(--font-display); font-size: 26px; color: #fff; background: linear-gradient(150deg, var(--pink), var(--violet)); }
.boot-mark span:last-child { background: linear-gradient(150deg, var(--cyan), #1a8dff); color: #071018; }
.boot-kicker { font-size: 8px; letter-spacing: .36em; color: var(--ink-dim); }
#boot h1 { margin: 0; font-family: var(--font-display); font-weight: 400; font-size: clamp(64px, 11vw, 138px); line-height: .8; letter-spacing: .03em; }
#boot h1 em { font-style: normal; color: transparent; background: linear-gradient(100deg, var(--pink), #ff8a3d, var(--gold)); -webkit-background-clip: text; background-clip: text; }
#boot p { margin: 4px 0 18px; font-size: 10px; letter-spacing: .16em; color: var(--ink-dim); }
.boot-actions { display: flex; align-items: center; gap: 16px; }
.boot-start {
  padding: 16px 52px; border: 0; cursor: pointer;
  font-family: var(--font-display); font-weight: 400; font-size: 26px; letter-spacing: .18em;
  color: #090711; background: linear-gradient(105deg, var(--cyan), var(--lime));
  clip-path: polygon(0 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
  box-shadow: 0 14px 44px rgba(37,244,255,.3); transition: transform .16s, filter .16s;
}
.boot-start:hover { transform: translateY(-2px); filter: brightness(1.12); }
.boot-status { display: flex; align-items: center; gap: 7px; font-size: 8px; font-weight: 700; letter-spacing: .14em; color: var(--lime); }
.spinner { width: 8px; height: 8px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 10px var(--lime); animation: blink 1.4s infinite; }
@keyframes blink { 50% { opacity: .25; } }
.boot-specs { display: flex; gap: 18px; margin-top: 28px; }
.boot-specs span { font-size: 8px; letter-spacing: .15em; color: var(--ink-dim); }
.boot-specs b { color: var(--cyan); font-family: var(--font-display); font-weight: 400; font-size: 19px; margin-right: 3px; }
.boot-footer { position: absolute; left: 24px; right: 24px; bottom: 18px; display: flex; justify-content: space-between; font-size: 7px; letter-spacing: .18em; color: rgba(255,255,255,.3); }

/* ================================================================
   RESPONSIVE
   ================================================================ */
@media (max-width: 1160px) {
  #topbar { gap: 10px; padding: 0 16px; }
  #main-tabs button { padding: 10px 9px; font-size: 10px; letter-spacing: .12em; }
  .brand-jp { display: none; }
  .garage-screen.is-active { grid-template-columns: 270px minmax(0,1fr) 320px; }
  .custom-layout { grid-template-columns: 255px minmax(0,1fr) 330px; }
  .ranks-layout { grid-template-columns: 290px minmax(0,1fr) 250px; }
  .race-location { min-width: 0; }
  .race-location b { font-size: 11px; }
}

@media (max-width: 940px) {
  #screen-root { padding: 14px 14px 12px; }
  #main-tabs { overflow-x: auto; justify-content: flex-start; max-width: 52vw; }
  #main-tabs::-webkit-scrollbar { display: none; }
  .cash-chip, .career-chip { display: none; }
  .garage-screen.is-active { grid-template-columns: 230px minmax(0,1fr); grid-template-rows: auto minmax(0,1fr) auto auto; }
  .garage-screen .garage-info { grid-column: 1 / -1; max-height: 330px; }
  .garage-bottom { justify-content: stretch; }
  .garage-bottom .cta { flex: 1; }
  .custom-layout { grid-template-columns: minmax(0,1fr) 330px; }
  .custom-stats { display: none; }
  .setup-layout { grid-template-columns: minmax(0,1fr) 290px; }
  .ranks-layout { grid-template-columns: 1fr 1fr; }
  .record-hero { grid-column: 1 / -1; }
  .rank-notes { grid-column: 1 / -1; }
  .rival-row { grid-template-columns: 34px 38px minmax(0,1fr) 110px; }
  .rival-specs { display: none; }
  .speed-digits b { font-size: 44px; }
  .race-rival-chip { display: none; }
  .race-tip-line { display: none; }
  .shift-module { width: 205px; }
  .pedal-module { width: 260px; }
}

@media (max-width: 740px) {
  #topbar { height: 60px; padding: 0 10px; }
  .brand-mark { width: 31px; height: 31px; }
  .brand-mark span { font-size: 16px; }
  .brand-name b, .brand-name em { font-size: 16px; }
  #main-tabs { max-width: none; flex: 1; }
  #main-tabs button { padding: 8px 7px; font-size: 9px; }
  #main-tabs button::after { left: 7px; right: 7px; }
  .icon-btn { width: 30px; height: 30px; }
  #screen-root { top: 60px; padding: 12px 10px 10px; }

  .home-screen.is-active { grid-template-columns: 1fr; grid-template-rows: auto auto auto; gap: 12px; padding: 6px 2px 0; }
  .hero-title { font-size: clamp(58px, 16vw, 92px); }
  .hero-sub { font-size: 11px; margin-bottom: 12px; }
  .hero-metrics { gap: 14px; margin-bottom: 14px; padding: 9px 0; }
  .hero-metrics b { font-size: 28px; }
  .home-copy > .cta { width: 100%; font-size: 12px; padding: 14px; }
  .home-build-card { padding: 13px; }
  .home-footer { flex-direction: column; align-items: flex-start; gap: 8px; }
  .home-tip { display: none; }
  .screen-title { font-size: 38px; }
  .screen-note { display: none; }
  .screen-head { align-items: flex-start; }
  .screen-head.compact { flex-direction: column; gap: 8px; }

  .garage-screen.is-active { display: flex; }
  .garage-list-panel { flex: 0 0 auto; max-height: 168px; }
  .garage-info { max-height: none !important; }
  .garage-bottom { flex-direction: column; }
  .garage-bottom .cta { width: 100%; }

  .dealer-layout { grid-template-columns: 1fr; }
  .dealer-detail { max-height: none; }
  .dealer-grid { grid-template-columns: repeat(auto-fill, minmax(125px, 1fr)); max-height: 46vh; }
  .dealer-browser { min-height: 0; }
  .dealer-wallet { padding: 7px 12px; }
  .dealer-wallet b { font-size: 22px; }
  .filter-row { flex-wrap: nowrap; overflow-x: auto; padding-bottom: 2px; }
  .filter-row button { white-space: nowrap; }

  .customize-screen.is-active { display: flex; }
  .custom-layout { grid-template-columns: 1fr; }
  .custom-shop { min-height: 62vh; }
  .custom-tabs { grid-template-columns: repeat(3, 1fr); }
  .part-grid { grid-template-columns: 1fr 1fr; }
  .custom-footer { flex-direction: column-reverse; }
  .custom-footer .cta { width: 100%; }

  .event-grid { grid-template-columns: 1fr; max-height: none; overflow: visible; }
  .event-footer { flex-direction: column; align-items: flex-start; gap: 8px; }

  .rival-row { grid-template-columns: 30px 34px minmax(0,1fr); padding: 9px; gap: 8px; }
  .rival-row .cta { grid-column: 1 / -1; width: 100%; }
  .rival-info p { font-size: 9px; }

  .setup-layout { grid-template-columns: 1fr; }
  .track-grid { grid-template-columns: repeat(2, 1fr); max-height: 40vh; }
