  .race-top { padding: 8px 10px 18px; gap: 8px; }
  #pause-btn { width: 30px; height: 30px; }
  .race-location small { display: none; }
  .race-location b { font-size: 9px; }
  .race-location span { font-size: 6.5px; }
  .race-clock-wrap { flex: 1; max-width: 46vw; }
