  } else if (name === 'dealer') {
    renderDealer();
    if (ui.dealerCar) setMenuCar(ui.dealerCar, DEFAULT_BUILD);
  } else if (name === 'customize') {
    if (!isOwned(ui.customCar)) ui.customCar = state.activeCar;
